insert into public.topics (id, name, description, aat_id) values
  ('culture.styles', 'Art & architecture styles', 'Styles, periods and movements in art, architecture and design: Gothic, Baroque, Art Nouveau, Cubism, Bauhaus, Brutalism, Pop art and the like, from the Getty Art & Architecture Thesaurus.', '300015646')
insert into public.topics (id, name, description, aat_id) values
  ('culture.styles.early_christian_byzantine', 'Early Christian-Byzantine styles, cultures, periods', 'Art & architecture styles › Early Christian-Byzantine styles, cultures, periods. AAT 300020658.', '300020658'),
  ('culture.styles.early_netherlandish', 'Early Netherlandish', 'The culture and the styles of art produced in the Southern Netherlands during the 15th and early 16th centuries. Also called Flemish Primitives. AAT 300387753.', '300387753'),
  ('culture.styles.hip_hop', 'Hip-hop', 'Cultural movement encompassing DJing, rap and rap music, dance and dance music, graffiti writing, and styles of dress. Also called hip hop. AAT 300266490.', '300266490'),
  ('culture.styles.medieval', 'Medieval', 'Refers to the period beginning in the Christianized Roman Empire in the fifth century and lasting until the Renaissance, which began in the 13th to the 15th century CE, depending upon which country is being discussed. Also called Mediaeval. AAT 300020756.', '300020756'),
  ('culture.styles.minimal', 'Minimalism', 'A style developed in the mid 20th century, characterized by simplicity and lack of decoration to the point of starkness. Also called ABC, Object Art. AAT 300065758.', '300065758'),
  ('culture.styles.modern_european', 'Modern European styles and movements', 'Art & architecture styles › Modern European styles and movements. AAT 300021424.', '300021424'),
  ('culture.styles.post_1945_architecture_design', 'Post-1945 architecture and design styles and movements', 'Art & architecture styles › Post-1945 architecture and design styles and movements. AAT 300111998.', '300111998'),
  ('culture.styles.post_1945_fine_arts', 'Post-1945 fine arts styles and movements', 'Art & architecture styles › Post-1945 fine arts styles and movements. AAT 300134574.', '300134574'),
  ('culture.styles.postmodern', 'Postmodernism', 'Refers to the style and period of art and architecture that developed in the 1960s and after, when there was a clear challenge to the dominance of Modernism. Also called P-M, Po-Mo. AAT 300022208.', '300022208'),
  ('culture.styles.punk', 'Punk', 'Style or movement characterized by the adoption of aggressively unconventional and often bizarre, violent, or shocking appearances and the defiance of social norms of behavior. AAT 300055797.', '300055797'),
  ('culture.styles.renaissance_baroque', 'Renaissance-Baroque styles and periods', 'Art & architecture styles › Renaissance-Baroque styles and periods. AAT 300021031.', '300021031'),
  ('culture.styles.space_age', 'Space age', 'Refers to the period from the mid-1950s through the early 1970s when rocketry was first used to launch satellites and manned missions, and its design. AAT 300266744.', '300266744'),
  ('culture.styles.early_christian_byzantine.byzantine', 'Byzantine', 'Culture, style, and period of the Christian states of the eastern Mediterranean during the rule of the Byzantine Empire (330 - 1453 CE). AAT 300020669.', '300020669'),
  ('culture.styles.early_christian_byzantine.early_christian', 'Early Christian', 'The culture, styles, and period of the first centuries of Christianity, by some reckonings through the 9th century. AAT 300020665.', '300020665'),
  ('culture.styles.medieval.early_medieval', 'Early Medieval', 'Refers to the periods and styles in Europe from the Migration period to the Romanesque period, roughly covering the fourth to the eleventh centuries. Also called Early Mediaeval. AAT 300020760.', '300020760'),
  ('culture.styles.medieval.gothic', 'Gothic', 'Refers to the style and period that began in northern France in the mid-twelfth century, and spread to the rest of western Europe during the next 100 years. Also called Pointed Style. AAT 300020775.', '300020775'),
  ('culture.styles.medieval.international_gothic', 'International Gothic', 'Refers to the style that developed in the French and Burgundian courts in the mid-14th century and spread widely over western Europe by about 1425. Also called International Style, Soft Style, Beautiful Style, Weicher Stil. AAT 300020786.', '300020786'),
  ('culture.styles.medieval.late_medieval', 'Late Medieval', 'The period c. 1250 to as late as 1500 where the terms Gothic or Late Gothic are not appropriate. Also called Late Mediaeval. AAT 300111307.', '300111307'),
  ('culture.styles.medieval.proto_renaissance', 'Proto-Renaissance', 'Refers to the style and period generally evident beginning in the mid-12th century in Italy and elsewhere in western Europe. AAT 300020787.', '300020787'),
  ('culture.styles.medieval.regional', 'Medieval regional styles', 'Regional styles belonging to Medieval cultures. Also called Medieval regional style. AAT 300021004.', '300021004'),
  ('culture.styles.medieval.romanesque', 'Romanesque', 'Refers to the style and period most evident during the 11th and 12th centuries in western Europe. AAT 300020768.', '300020768'),
  ('culture.styles.modern_european.architecture', 'Modern European architecture styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European architecture styles and movements. AAT 300021485.', '300021485'),
  ('culture.styles.modern_european.art_deco', 'Art Deco', 'Refers to the style predominantly of architecture and the decorative arts, widely disseminated in Europe and the United States in the 1920s and 1930s. Also called American Deco, Art Décoratif, Art Moderne. AAT 300021426.', '300021426'),
  ('culture.styles.modern_european.art_nouveau', 'Art Nouveau', 'Refers generally to the style of painting, architecture, decorative arts, and applied arts that flourished in Europe and the United States from about 1890 to 1910. AAT 300021430.', '300021430'),
  ('culture.styles.modern_european.biedermeier', 'Biedermeier', 'Satirical name used to describe a style of Central European arts prevalent from the 1820s to the 1850s, that became associated with the taste of the middle class. AAT 300021434.', '300021434'),
  ('culture.styles.modern_european.celtic_revival', 'Celtic Revival', 'A variety of movements and trends in the 19th and 20th centuries that saw a renewed interest in aspects of Celtic culture. Also called Celtic Twilight. AAT 300438586.', '300438586'),
  ('culture.styles.modern_european.decorative_arts', 'Modern European decorative arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European decorative arts styles and movements. AAT 300021490.', '300021490'),
  ('culture.styles.modern_european.expressionist', 'Expressionism', 'Refers to an international style of art, literature, music, dance, and theater that flourished between 1905 and 1920, especially in Germany. AAT 300021502.', '300021502'),
  ('culture.styles.modern_european.fin_de_siecle', 'Fin de siècle', 'Refers broadly to the arts of the last two decades of the 19th century. Also called Fin-de-Siècle. AAT 300111540.', '300111540'),
  ('culture.styles.modern_european.fine_arts', 'Modern European fine arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European fine arts styles and movements. AAT 300021494.', '300021494'),
  ('culture.styles.modern_european.hutsul_style', 'Hutsul Style', 'Folk art style of the Hutsul people or styles influenced by the folk art of the Hutsul people, including Art Nouveau styles. AAT 300403937.', '300403937'),
  ('culture.styles.modern_european.modernist', 'Modernism', 'Refers to the succession of 20th-century avant-garde art and architectural movements formed in a reaction to social modernity. AAT 300021474.', '300021474'),
  ('culture.styles.modern_european.nazarene', 'Nazarenism', 'The work of the "Lukasbrüder", a group founded in Vienna in 1809 by Friedrich Overbeck, later derisively called "Nazarenes". Also called Nazarene School. AAT 300265658.', '300265658'),
  ('culture.styles.modern_european.neo_romantic', 'Neo-Romanticism', 'Refers to the British style affecting art, literature, theater, and film and dating between the 1930s and the 1950s. Also called Neo-Romanticist. AAT 300021476.', '300021476'),
  ('culture.styles.modern_european.neoclassical', 'Neoclassicism', 'Refers to the style of European and American architecture and fine and decorative arts between the mid-18th century and the mid-19th century inspired by archaeological discoveries. Also called Neoclassic, Neo-Classical. AAT 300021477.', '300021477'),
  ('culture.styles.modern_european.pointillist', 'Pointillism', 'Style of painting resulting from the technique of pointillism, which uses dots or short dashes of unmixed color to create images. AAT 300419441.', '300419441'),
  ('culture.styles.modern_european.pre_war_style', 'Pre-war style', 'Style of buildings constructed before 1939, arising during a population boom in Europe in the 1880s. AAT 300444902.', '300444902'),
  ('culture.styles.modern_european.proto_expressionist', 'Proto-Expressionism', 'Styles having elements that anticipated and had a profound influence on Expressionist art, literature, and dramatic arts. AAT 300403931.', '300403931'),
  ('culture.styles.modern_european.regional', 'Modern European regional styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements. AAT 300021175.', '300021175'),
  ('culture.styles.modern_european.revival', 'Modern European revival styles', 'Modern revival styles belonging to European cultures. Also called modern European revival style. AAT 300021442.', '300021442'),
  ('culture.styles.modern_european.romantic', 'Romanticism', 'Refers to the European movement affecting visual arts, literature, music, and to a lesser degree architecture from the mid-18th to the mid-19th centuries. Also called Romanticist, Romantic movement. AAT 300172863.', '300172863'),
  ('culture.styles.modern_european.secession_movement', 'Secession Movement', 'Describes the works of the groups of German and Austrian artists who rebelled against the Salon system and exhibited independently at the end of the 19th century. Also called Secession, Sezession. AAT 300111580.', '300111580'),
  ('culture.styles.post_1945_architecture_design.brutalist', 'Brutalism', 'Refers to a style of architecture dependent on exposed rough concrete as structural form, particularly dating to the 1960s and 1970s. Also called Neo-Brutalism, New Brutalism. AAT 300112048.', '300112048'),
  ('culture.styles.post_1945_architecture_design.deconstructivist', 'Deconstructivism', 'Refers to the architecture derived from the philosophical and literary movement associated with Jacques Derrida in the 1960s. Also called Deconstruction. AAT 300112407.', '300112407'),
  ('culture.styles.post_1945_architecture_design.desert_modernism', 'Desert Modernism', 'Architectural style of Modernist or International Style origins, tailored to the indoor-outdoor lifestyle and aesthetics of desert communities. Also called Desert Modern, Palm Springs Modern. AAT 300457625.', '300457625'),
  ('culture.styles.post_1945_architecture_design.googie', 'Googie', 'Style of architecture and design first popular in the United States in the 1950s, typified by roadside buildings such as coffee shops, motels and gas stations. Also called Populuxe. AAT 300265600.', '300265600'),
  ('culture.styles.post_1945_architecture_design.high_tech', 'High-Tech', 'Architectural and interior design popular in Europe and North America in the 1970s. Also called Industrial Aesthetic, High Tech. AAT 300060022.', '300060022'),
  ('culture.styles.post_1945_architecture_design.memphis', 'Memphis', 'Design group founded in Milan in 1980 by Ettore Sottsass and others. Also called Memphis movement, Memphis style, Memphis Group. AAT 300265730.', '300265730'),
  ('culture.styles.post_1945_architecture_design.metabolism', 'Metabolism', 'Japanese architectural movement of the 1960s and 1970s, dedicated to urban-scale issues based on biologic principles of dynamic growth and change. Also called Metabolist, Metabolism in architecture. AAT 300259277.', '300259277'),
  ('culture.styles.post_1945_architecture_design.mid_century_modernist', 'Mid-Century Modernism', 'Refers to the architectural, interior and product design style of mid-20th century trends from ca. 1933 to 1965. Also called Mid-Century Modern, Midcentury Modern. AAT 300343610.', '300343610'),
  ('culture.styles.post_1945_architecture_design.neo_rationalist', 'Neo-Rationalism', 'Art & architecture styles › Post-1945 architecture and design styles and movements › Neo-Rationalism. Also called Neorationalism, Neorationalist. AAT 300124068.', '300124068'),
  ('culture.styles.post_1945_architecture_design.nuovo_design', 'Nuovo Design', 'Design movement which emerged in Italy in the 1960s and 1970s. AAT 300112822.', '300112822'),
  ('culture.styles.post_1945_architecture_design.post_functionalism', 'Post-Functionalism', 'Architecture style espoused by Sol LeWitt and Giuseppe Terragni. AAT 300265663.', '300265663'),
  ('culture.styles.post_1945_architecture_design.structural_classicism', 'Structural Classicism', 'Movement in architecture that uses structure as the fundamental expression, endorsing structural and material changes enabled by the industrial revolution. AAT 300444985.', '300444985'),
  ('culture.styles.post_1945_fine_arts.abstract_expressionist', 'Abstract Expressionism', 'Refers to the movement in American painting, centered mainly in New York, that flourished in the 1940s and 1950s. Also called Abstract-Expressionist, American-Type painting. AAT 300022099.', '300022099'),
  ('culture.styles.post_1945_fine_arts.abstract_impressionist', 'Abstract Impressionism', 'Refers to the style named by Elaine de Kooning to describe works painted with uniform brushstrokes that retain the optical qualities of Impressionism. AAT 300022107.', '300022107'),
  ('culture.styles.post_1945_fine_arts.afrofuturist', 'Afrofuturism', 'A primarily African-American movement in literature, music, and visual art that focuses on themes from science fiction or an imagined future. Also called Afro-futurism. AAT 300410340.', '300410340'),
  ('culture.styles.post_1945_fine_arts.are_bure_boke', 'Are, bure, boke', 'Japanese phrase translated as "grainy, blurry, and out-of-focus", a style of photography popularized in Japan in the late 1960s. Also called are-bure-boke. AAT 300412039.', '300412039'),
  ('culture.styles.post_1945_fine_arts.art_informel', 'Art Informel', 'Refers to the European movement in painting which, beginning around 1945, ran parallel with Abstract Expressionism in North America. Also called Art Autre, Art Without Form. AAT 300022176.', '300022176'),
  ('culture.styles.post_1945_fine_arts.arte_nucleare', 'Arte nucleare', 'Refers to an Italian painting movement of the 1950s, co-founded by Enrico Baj, Sergio Dangelo and Gianni Bertini, promoting gestural painting. Also called Movimento Nucleare. AAT 300404596.', '300404596'),
  ('culture.styles.post_1945_fine_arts.arte_povera', 'Arte Povera', 'Refers to the Italian art movement of the 1970s that was analogous to the Minimalist and Conceptual Art movement in North America. Also called Art Povera, Impoverished Art. AAT 300047851.', '300047851'),
  ('culture.styles.post_1945_fine_arts.bad_painting', 'Bad Painting', 'Refers to the style of painting popular in the late 1970s and early 1980s, produced by professionally trained artists, which is self-consciously inept. Also called Bad Art. AAT 300263413.', '300263413'),
  ('culture.styles.post_1945_fine_arts.bioart', 'Bioart', 'A contemporary art form that adapts scientific methods and draws inspiration from the implications of biotechnology. Also called bio art. AAT 300443553.', '300443553'),
  ('culture.styles.post_1945_fine_arts.chicago_imagist', 'Chicago Imagism', 'Refers to the work of a group of artists working in Chicago who gained national recognition in 1959. Also called Hairy Who. AAT 300116666.', '300116666'),
  ('culture.styles.post_1945_fine_arts.cobra', 'CoBrA', 'Refers to the expressionistic style inspired by children''s art characteristic of a group formed in 1948 by artists from Copenhagen, Brussels, and Amsterdam. AAT 300411283.', '300411283'),
  ('culture.styles.post_1945_fine_arts.color_field', 'Color-field', 'Encompasses both Abstract Imagist painting and works of the 1960s derived from it. Also called Color Field painting. AAT 300022120.', '300022120'),
  ('culture.styles.post_1945_fine_arts.conceptual', 'Conceptual art', 'Refers broadly to a variety of art created in the 1960s and 1970s in which the idea is the work. Also called Concept art, Idea art. AAT 300264827.', '300264827'),
  ('culture.styles.post_1945_fine_arts.constructionist', 'Constructionism', 'Style and movement that grew out of Constructivism. AAT 300018236.', '300018236'),
  ('culture.styles.post_1945_fine_arts.context_art', 'Context Art', 'A term referring to an artmaking practice or trend coined in the early 1990s. Also called Kontext-Kunst. AAT 300435204.', '300435204'),
  ('culture.styles.post_1945_fine_arts.critical_figuration', 'Critical Figuration', 'French art movement founded in Paris in 1978. AAT 300457783.', '300457783'),
  ('culture.styles.post_1945_fine_arts.dau_al_set', 'Dau al Set', 'Catalan avant-garde movement in art and literature, founded in Barcelona in 1948 and active until the early 1950s. AAT 300451041.', '300451041'),
  ('culture.styles.post_1945_fine_arts.direct_art', 'Direct art', 'Refers to a movement formed of a group of Austrian artists active in the 1960s. Also called Viennese Actionism, actionism. AAT 300047933.', '300047933'),
  ('culture.styles.post_1945_fine_arts.eat_art', 'Eat Art', 'Modern art tendency attributed to Daniel Spoerri, who opened the Eat Art Gallery in Düsseldorf in 1970. AAT 300435167.', '300435167'),
  ('culture.styles.post_1945_fine_arts.eccentric_abstraction', 'Eccentric Abstraction', 'Refers to the style predominantly of sculpture that first appeared in an art exhibition in 1966. AAT 300192655.', '300192655'),
  ('culture.styles.post_1945_fine_arts.fantastic_realist', 'Fantastic Realism', 'Refers to a style of Austrian painting that appeared in Vienna around 1945. Also called Phantastischer Realismus. AAT 300022160.', '300022160'),
  ('culture.styles.post_1945_fine_arts.fluxus', 'Fluxus', 'Refers to the international avant-garde art and literary movement begun officially in 1962, and active throughout the 1960s and 1970s. AAT 300022168.', '300022168'),
  ('culture.styles.post_1945_fine_arts.funk', 'Funk', 'First used to describe the work of a group of artists working in San Francisco in the late 1950s. AAT 300047891.', '300047891'),
  ('culture.styles.post_1945_fine_arts.gutai', 'Gutai', 'The movement associated with the Gutai Art Association, a collective of vanguard artists founded in Ashiya, Japan, in 1954 and disbanded in 1972. AAT 300417399.', '300417399'),
  ('culture.styles.post_1945_fine_arts.hard_edge', 'Hard-edge', 'Refers to the paintings of a group of West Coast artists working in the 1960s. Also called Abstract Classicism, Hard edge. AAT 300022175.', '300022175'),
  ('culture.styles.post_1945_fine_arts.hyperrealist', 'Hyperrealism', 'Refers to the movement or style evolving from Photorealism in the United States and Europe. Also called Hyper Realism. AAT 300404781.', '300404781'),
  ('culture.styles.post_1945_fine_arts.kinetic_art', 'Kinetic Art', 'Refers broadly to artworks in a variety of styles that incorporate some aspect of motion, including machines, mobiles, and actual objects in motion. Also called Kineticism. AAT 300069473.', '300069473'),
  ('culture.styles.post_1945_fine_arts.lettrist', 'Lettrism', 'Refers to the international avant-garde art and poetry movement based in Paris and begun by Romanian writer Isidore Isou in 1945. Also called Lettrisme. AAT 300022180.', '300022180'),
  ('culture.styles.post_1945_fine_arts.light_and_space', 'Light and Space', 'Refers to a form of minimalism credited to Southern California artists of the 1960s and 1970s characterized by a preoccupation with light and transparency. Also called Light and Space Movement. AAT 300375712.', '300375712'),
  ('culture.styles.post_1945_fine_arts.lyrical_abstraction', 'Lyrical Abstraction', 'Refers to certain works that continued Abstract Expressionism into the 1960s and 1970s (e.g., by Guston, Frankenthaler). AAT 300056510.', '300056510'),
  ('culture.styles.post_1945_fine_arts.matter_art', 'Matter art', 'Refers to the style of painting from the 1950s until the 1970s characterized by thick, crusted paint and the incorporation of discarded materials. Also called Matterism, Matiere Painting. AAT 300108310.', '300108310'),
  ('culture.styles.post_1945_fine_arts.mexican_modernist', 'Mexican Modernism', 'Artistic movement that flourished in Mexico in the early 1920s, following the Mexican Revolution. AAT 300451411.', '300451411'),
  ('culture.styles.post_1945_fine_arts.neo_constructivist', 'Neo-Constructivism', 'Post-1945 art movement building upon some of the aesthetic principles of Constructivism. AAT 300112846.', '300112846'),
  ('culture.styles.post_1945_fine_arts.neo_dada', 'Neo-Dadaism', 'Refers to the style of painting and sculpture inspired by the Dada movement, first seen in the works of Jasper Johns and Robert Rauschenberg in the late 1950s. Also called Proto-Pop. AAT 300022187.', '300022187'),
  ('culture.styles.post_1945_fine_arts.neo_expressionist', 'Neo-Expressionism', 'Refers to the style of art, predominantly of painting, inspired by German Expressionism that gained popularity in Italy, Germany, and America in the late 1970s and early 1980s. Also called New Wave. AAT 300022189.', '300022189'),
  ('culture.styles.post_1945_fine_arts.neo_geo', 'Neo-Geo', 'Refers to the work of a group of artists exhibiting in New York in the mid-1980s. Also called Simulationist. AAT 300265635.', '300265635'),
  ('culture.styles.post_1945_fine_arts.neo_pop', 'Neo-Pop', 'Postmodern movement in the visual arts of the 1980s in which artists were influenced by pop art. AAT 300251301.', '300251301'),
  ('culture.styles.post_1945_fine_arts.neue_rheinische_sezession', 'Neue Rheinische Sezession', 'Refers to the work of a group of artists that was formed in Germany in 1949. AAT 300112462.', '300112462'),
  ('culture.styles.post_1945_fine_arts.new_figuration', 'New Figuration', 'Refers to the style of painting popular in the early 1960s in Paris, London and New York. Also called Nouvelle Figuration. AAT 300022191.', '300022191'),
  ('culture.styles.post_1945_fine_arts.new_image', 'New Image', 'Refers to the style of painting and sculpture popular in the late 1970s in Europe and the United States. Also called New Image Painting. AAT 300263416.', '300263416'),
  ('culture.styles.post_1945_fine_arts.new_italian_manner', 'New Italian Manner', 'Refers to a style of painting that combines science and art, mythology and history, updating 16th-century Mannerism. Also called Neo-Mannerism, Nuova maniera italiana. AAT 300265764.', '300265764'),
  ('culture.styles.post_1945_fine_arts.new_modernist', 'New Modernism', 'Refers to the international movement in architecture begun in the late 1970s. AAT 300263439.', '300263439'),
  ('culture.styles.post_1945_fine_arts.new_topographics', 'New Topographics', 'Describes a photographic movement identified in a 1975 exhibition organized by William Jenkins at the George Eastman House. AAT 300411288.', '300411288'),
  ('culture.styles.post_1945_fine_arts.nouveau_realisme', 'Nouveau Réalisme', 'Mostly French art of the 1960s that is realist in the sense of appropriating materials from the environment or staging actions or happenings. Also called New Realism, New Realist. AAT 300112105.', '300112105'),
  ('culture.styles.post_1945_fine_arts.op_art', 'Op art', 'Refers to the international art movement that flourished in Europe and America in the mid-1960s. Also called Op, Optical. AAT 300022195.', '300022195'),
  ('culture.styles.post_1945_fine_arts.pattern_painting', 'Pattern painting', 'Movement of Matisse-influenced decorative painting in New York in the 1970s. Also called Pattern and decoration, Decorationist. AAT 300022198.', '300022198'),
  ('culture.styles.post_1945_fine_arts.photorealist', 'Photorealism', 'Refers to the international movement in painting and sculpture that became popular in the late 1960s and early 1970s. Also called New Realism, Photo Realist. AAT 300022201.', '300022201'),
  ('culture.styles.post_1945_fine_arts.pittura_colta', 'Pittura Colta', 'Refers to the historicizing, classicizing movement in Italian painting of the 1980s. Also called Anachronism, Hyper-Mannerism. AAT 300073920.', '300073920'),
  ('culture.styles.post_1945_fine_arts.pop', 'Pop art', 'Refers to the international art and cultural movement that flourished in Britain and America in the 1950s and 1960s. Also called Industrial Art. AAT 300022205.', '300022205'),
  ('culture.styles.post_1945_fine_arts.post_conceptual', 'Post-conceptual art', 'Art & architecture styles › Post-1945 fine arts styles and movements › Post-conceptual art. AAT 300116825.', '300116825'),
  ('culture.styles.post_1945_fine_arts.postminimal', 'Postminimal', 'Refers broadly to a variety of art that developed in the late 1970s, the term coined by American art critic Robert Pincus-Witten. Also called Post-Minimalism. AAT 300112731.', '300112731'),
  ('culture.styles.post_1945_fine_arts.process_art', 'Process art', 'Refers to art in which the process of creating it becomes the subject matter. Also called Procedural art. AAT 300022209.', '300022209'),
  ('culture.styles.post_1945_fine_arts.psychedelic', 'Psychedelic', 'Refers to the art and cultural movement of the mid- to late 1960s that was international in scope, but flourished mainly on the American West Coast. Also called Acid Art. AAT 300112743.', '300112743'),
  ('culture.styles.post_1945_fine_arts.radical_realist', 'Radical Realism', 'A style or movement that began in the late 1960s among a group of artists working concurrently with Pop artists and Photorealists. AAT 300404783.', '300404783'),
  ('culture.styles.post_1945_fine_arts.relational_art', 'Relational art', 'Theorized by French curator and critic Nicolas Bourriaud in the late 1990s, art practices taking human relations and their social context as their point of departure. Also called Relational aesthetics. AAT 300391190.', '300391190'),
  ('culture.styles.post_1945_fine_arts.severe_style', 'Severe Style', 'An aesthetic trend in the post-Stalinist Soviet Union (late 1950s – 1970s), often referred to as the official art of the Khrushchev thaw. AAT 300417419.', '300417419'),
  ('culture.styles.post_1945_fine_arts.situationist', 'Situationism', 'Refers to the work of a group of avant-garde artists and cultural theorists active in several European countries from 1957 to 1972. Also called Internationale Situationniste. AAT 300179513.', '300179513'),
  ('culture.styles.post_1945_fine_arts.sky_art', 'Sky art', 'Movement centered around artist Otto Piene and the Center for Advanced Visual Studies at the Massachusetts Institute of Technology. AAT 300265833.', '300265833'),
  ('culture.styles.post_1945_fine_arts.spatialist', 'Spatialism', 'Refers to the works of art associated with the aesthetic doctrines developed by Argentine-Italian artist Lucio Fontana (1899-1968). Also called Movimento spaziale, Spazialismo. AAT 300111605.', '300111605'),
  ('culture.styles.post_1945_fine_arts.structurist', 'Structurism', 'The style and movement, growing out of Constructionism, that emphasizes the underlying structural forms and processes found in nature. AAT 300419962.', '300419962'),
  ('culture.styles.post_1945_fine_arts.stuckist', 'Stuckism', 'Refers to the art group co-founded in 1999 by British artists Charles Thomson and Billy Childish, along with eleven other artists. AAT 300265674.', '300265674'),
  ('culture.styles.post_1945_fine_arts.subjective_photography', 'Subjective photography', 'Refers to the works of a group of photographers working in Western Europe in the 1950s who were influenced by the teaching of Otto Steinert. AAT 300181199.', '300181199'),
  ('culture.styles.post_1945_fine_arts.supermannerist', 'Supermannerism', 'Refers to the trend in American interior design of the late 1960s, the term coined by Progressive Architecture magazine. Also called Mega-decoration. AAT 300132708.', '300132708'),
  ('culture.styles.post_1945_fine_arts.supports_surfaces', 'Supports/Surfaces', 'Avant-garde movement in painting in France from the later 1960s and early 1970s characterized by a radically different approach to painted surfaces. AAT 300451040.', '300451040'),
  ('culture.styles.post_1945_fine_arts.systemic', 'Systemic', 'Abstract paintings of the 1960s and 1970s that repeat or vary a motif from work to work or within a work. AAT 300112839.', '300112839'),
  ('culture.styles.post_1945_fine_arts.systems_art', 'Systems art', 'Art influenced by systems analysis, dealing, for example, with systems of natural phenomena, social signs, or the art world itself. AAT 300047869.', '300047869'),
  ('culture.styles.post_1945_fine_arts.trans_avantgarde', 'Trans-avantgarde', 'Term coined by critic Achille Bonito Oliva for a trend in Italian art, especially painting, of the late 1970s and early 1980s that embraced hand craftsmanship. Also called Transavanguardia, Transavantgarde, trans-avant-garde. AAT 300022218.', '300022218'),
  ('culture.styles.post_1945_fine_arts.young_british_art', 'Young British Art', 'Refers to the work of a group of artists exhibiting in London in the late 1980s and 1990s. Also called Young British Artists, YBA. AAT 300263412.', '300263412'),
  ('culture.styles.renaissance_baroque.baroque', 'Baroque', 'Refers to the style and period of architecture, visual art, decorative art, music, and literature of western Europe and the Americas from about 1590 to 1750. AAT 300021147.', '300021147'),
  ('culture.styles.renaissance_baroque.counter_reformation', 'Counter-Reformation', 'Refers to the period of internal renewal in the Roman Catholic Church following and in opposition to the Protestant Reformation in the 16th and early 17th centuries. Also called Catholic Reformation, Catholic Revival. AAT 300022045.', '300022045'),
  ('culture.styles.renaissance_baroque.reformation', 'Reformation', 'Refers to the period of the religious revolution that took place in the Christian church of central and northwestern Europe in the 16th century. Also called Protestant Reformation. AAT 300022041.', '300022041'),
  ('culture.styles.renaissance_baroque.renaissance', 'Renaissance', 'Refers to the intellectual movement, style, and culture that originated in Italy in the late 14th century, spread throughout Europe, and culminated in the 16th century. AAT 300021140.', '300021140'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles', 'Renaissance-Baroque styles', 'Styles belonging to Renaissance-Baroque cultures. Also called Renaissance-Baroque style. AAT 300021033.', '300021033'),
  ('culture.styles.renaissance_baroque.rococo', 'Rococo', 'Refers to that period primarily of decorative art that emerged in France ca. 1700. AAT 300021155.', '300021155'),
  ('culture.styles.early_christian_byzantine.byzantine.early_byzantine', 'Early Byzantine', 'Refers to the early stages of the Byzantine period that began when the Emperor Constantine made Byzantium the new capital of the Roman Empire in 330 CE. AAT 300106792.', '300106792'),
  ('culture.styles.early_christian_byzantine.byzantine.late_byzantine', 'Late Byzantine', 'Refers to the revival of Byzantine style and western influence that evolved after the Crusades in Byzantium and eastern Europe in the late 13th century. AAT 300020676.', '300020676'),
  ('culture.styles.early_christian_byzantine.byzantine.latin_empire', 'Latin Empire', 'Refers to the period and culture surrounding the conquest and colonization of the Byzantine Empire by the West following the Fourth Crusade. Also called Latin Dynasty, Latin Kingdom. AAT 300020698.', '300020698'),
  ('culture.styles.early_christian_byzantine.byzantine.middle_byzantine', 'Middle Byzantine', 'Refers to the style following the Iconoclastic crisis, from the mid-ninth century through the early 13th century. Also called Second Golden Age, Mid-Byzantine. AAT 300020674.', '300020674'),
  ('culture.styles.early_christian_byzantine.byzantine.post_byzantine', 'Post-Byzantine', 'Refers to art produced by Orthodox Christians living in lands once part of the Byzantine empire. AAT 300379797.', '300379797'),
  ('culture.styles.early_christian_byzantine.byzantine.regional', 'Byzantine regional styles', 'Regional styles belonging to Byzantine cultures. Also called Byzantine regional style. AAT 300020678.', '300020678'),
  ('culture.styles.medieval.early_medieval.carolingian', 'Carolingian', 'Refers to the culture, period, and style surrounding the reign of Charlemagne (768-814) and his successors through about 900 CE. Also called Carlovingian, Carolingian Renaissance. AAT 300020764.', '300020764'),
  ('culture.styles.medieval.early_medieval.migration_period', 'Migration period', 'Refers to the period and style of art produced by the Teutonic tribes who overran the declining Roman Empire from about 370 CE to about 800 CE. Also called Migration, Dark Ages. AAT 300106913.', '300106913'),
  ('culture.styles.medieval.early_medieval.ottonian', 'Ottonian', 'Refers to the period, style, and culture associated with the rule of the Ottonian emperors (919-1024) and Salian rulers Conrad II and Henry III, through most of the 11th century. AAT 300020766.', '300020766'),
  ('culture.styles.medieval.gothic.brabantine_gothic', 'Brabantine Gothic', 'Gothic architecture style typical of the Low Countries, surfacing in the first half of the 14th century at Saint Rumbold''s Cathedral in Mechelen. Also called Brabantian Gothic. AAT 300440739.', '300440739'),
  ('culture.styles.medieval.gothic.cistercian_gothic', 'Cistercian Gothic', 'Style associated with the Cistercians, incorporating the tenets of Bernard of Clairvaux and representing a transition between Romanesque and Gothic. AAT 300410352.', '300410352'),
  ('culture.styles.medieval.gothic.early_gothic', 'Early Gothic', 'Refers to the early phases of the style and period that flourished in the Île-de-France with the emergence of the strong French monarchy in the mid-12th century. Also called 1200 Style, Transitional Style. AAT 300020780.', '300020780'),
  ('culture.styles.medieval.gothic.french_gothic', 'French Gothic', 'The Gothic style of architecture and sculpture as practiced in France from 1140 until about 1500. AAT 300440779.', '300440779'),
  ('culture.styles.medieval.gothic.high_gothic', 'High Gothic', 'Refers to the period and style of Gothic art of the late 12th through the 13th centuries in France and elsewhere in Europe, marked by the achievement of Gothic ideals in architecture and other arts. AAT 300020782.', '300020782'),
  ('culture.styles.medieval.gothic.late_gothic', 'Late Gothic', 'Refers to the last years of the Gothic period and style in architecture and other arts in Europe, beginning in the late 13th century. AAT 300020783.', '300020783'),
  ('culture.styles.medieval.regional.crusader', 'Crusader', 'Refers to the style and period associated with the Crusades of 1096 to 1291 and subsequent settlement of European Christians in the Holy Land and eastern Mediterranean area through the 15th century. Also called Crusader Style. AAT 300020700.', '300020700'),
  ('culture.styles.medieval.regional.migration_period', 'Migration period styles', 'Styles belonging to Migration period cultures. Also called Migration period style. AAT 300106978.', '300106978'),
  ('culture.styles.medieval.regional.northern_european', 'Northern European Medieval styles', 'Styles belonging to Northern European Medieval cultures. Also called Northern European Medieval style. AAT 300111912.', '300111912'),
  ('culture.styles.medieval.regional.southern_european', 'Southern European Medieval styles', 'Styles belonging to Southern European Medieval cultures. Also called Southern European Medieval style. AAT 300111915.', '300111915'),
  ('culture.styles.modern_european.architecture.anglo_mediterranean', 'Anglo-Mediterranean', 'Refers to the architectural style of villas built for the British on the French and Italian Rivieras. AAT 300266392.', '300266392'),
  ('culture.styles.modern_european.architecture.beaux_arts', 'Beaux-Arts', 'Refers to the style of architecture and city planning originally taught at the École des Beaux-Arts in Paris in the 19th and 20th centuries. Also called Beaux-Arts tradition. AAT 300021433.', '300021433'),
  ('culture.styles.modern_european.architecture.international_style', 'International Style', 'Refers to the style of architecture that emerged in Holland, France, and Germany after World War I and spread throughout the world. Also called International Modern. AAT 300021472.', '300021472'),
  ('culture.styles.modern_european.architecture.modern_movement', 'Modern Movement', 'The collective actions and objectives of Modernist architecture, especially, but not exclusively, of the International Style. AAT 300121793.', '300121793'),
  ('culture.styles.modern_european.architecture.neues_bauen', 'Neues Bauen', 'Refers to a trend among the German architectural avant-garde of the mid-1920s that promoted practical functionalism. Also called Nieuwe Zakelijkheid, Nieuwe Bouwen. AAT 300111557.', '300111557'),
  ('culture.styles.modern_european.architecture.rationalist', 'Rationalism', 'Architectural style that developed particularly in Italy in the 1920s and 1930s, emphasizing a scientific and rational approach to design. Also called Italian Rationalism. AAT 300457776.', '300457776'),
  ('culture.styles.modern_european.architecture.swiss_chalet_style', 'Swiss chalet style', 'A romanticized architectural style of the latter part of the 19th and early 20th century inspired by chalets in Switzerland. Also called chalet style. AAT 300411462.', '300411462'),
  ('culture.styles.modern_european.decorative_arts.abbotsford', 'Abbotsford', 'Refers to a style of imitation Gothic furniture in the 1820s and 1830s. Also called Baronial. AAT 300021491.', '300021491'),
  ('culture.styles.modern_european.decorative_arts.anglo_japanese', 'Anglo-Japanese', 'Decorative arts style for furnishings pioneered by designer and architect Thomas Jeckyll (1827-1881), featuring Japanese-inspired ornamentation. AAT 300265613.', '300265613'),
  ('culture.styles.modern_european.decorative_arts.ceramics', 'Modern European ceramics styles', 'Ceramics styles belonging to modern European cultures. Also called modern European ceramics style. AAT 300111457.', '300111457'),
  ('culture.styles.modern_european.decorative_arts.japonaiserie', 'Japonaiserie', 'Refers to late-19th-century Japanese-style European and American decorative arts and architecture characterized by asymmetrical compositions and Japanese motifs. Also called Japanesery. AAT 300021492.', '300021492'),
  ('culture.styles.modern_european.decorative_arts.neo_louis_xiv', 'Neo-Louis XIV', 'Historicist architectural and furniture style developed in the third and fourth quarters of the 19th century. AAT 300455796.', '300455796'),
  ('culture.styles.modern_european.decorative_arts.neo_louis_xv', 'Neo-Louis XV', 'Historicist architecture style developed around 1910. AAT 300455797.', '300455797'),
  ('culture.styles.modern_european.decorative_arts.neo_louis_xvi', 'Neo-Louis XVI', 'Historicist architecture style developed from the latter 19th century onwards. AAT 300455798.', '300455798'),
  ('culture.styles.modern_european.decorative_arts.rustic', 'Rustic', 'Refers to the style of 18th and 19th century European and American architecture and furniture that mimics rough hewn logs or parts of a tree in its construction or decoration. AAT 300018229.', '300018229'),
  ('culture.styles.modern_european.expressionist.german_expressionist', 'German Expressionism', 'A number of related creative movements in Germany before the First World War that reached a peak in Berlin during the 1920s. AAT 300438588.', '300438588'),
  ('culture.styles.modern_european.fin_de_siecle.belle_epoque', 'Belle époque', 'Refers generally to any period of high artistic or cultural development. Also called belle epoque. AAT 300264407.', '300264407'),
  ('culture.styles.modern_european.fin_de_siecle.decadent_movement', 'Decadent Movement', 'Refers to the intellectual movement of the last two decades of the 19th century when artists and writers became more concerned with form, beauty, and pleasure than content. Also called Decadence, Decadent. AAT 300021439.', '300021439'),
  ('culture.styles.modern_european.fine_arts.abstract', 'Abstract art', 'Refers to art styles that were a reaction against the traditional European conception of art as the imitation of nature. AAT 300108127.', '300108127'),
  ('culture.styles.modern_european.fine_arts.barbizon_school', 'Barbizon School', 'An informal group of painters centered in the village of Barbizon at the edge of the Forest of Fontainebleau. Also called Barbizon. AAT 300264658.', '300264658'),
  ('culture.styles.modern_european.fine_arts.camden_town_group', 'Camden Town Group', 'Style tied to the exhibiting society of 16 British painters active primarily between 1911 and 1914. AAT 300440776.', '300440776'),
  ('culture.styles.modern_european.fine_arts.concrete_art', 'Concrete art', 'Term coined in 1930 by Theo van Doesburg to characterize a form of non-figurative painting in which the pictorial elements, planes and colors, have no significance other than themselves. Also called Art Concret. AAT 300021436.', '300021436'),
  ('culture.styles.modern_european.fine_arts.cubist', 'Cubism', 'Refers to the international art movement with origins attributed to Georges Braque and Pablo Picasso ca. 1907. AAT 300021495.', '300021495'),
  ('culture.styles.modern_european.fine_arts.dada', 'Dadaism', 'Refers to the European artistic and literary movement of revolt against the pretensions of Western civilization, begun in Zurich in 1916 as a reaction to World War I. Also called Dadaist. AAT 300021500.', '300021500'),
  ('culture.styles.modern_european.fine_arts.die_brucke', 'Die Brücke', 'Describes the style of the German group of painters and printmakers active from 1905 to 1913, closely associated with the development of Expressionism. AAT 300440790.', '300440790'),
  ('culture.styles.modern_european.fine_arts.impressionist', 'Impressionism', 'Refers to the movement in 19th-century Western art that developed in France and rejected traditional academic teaching. AAT 300021503.', '300021503'),
  ('culture.styles.modern_european.fine_arts.leibl_kreis', 'Leibl-Kreis', 'Describes the style of a group of artists who were associates of Wilhelm Leibl between 1871 and 1873. Also called Leibl circle. AAT 300440782.', '300440782'),
  ('culture.styles.modern_european.fine_arts.magic_realist', 'Magic Realism', 'Art & architecture styles › Modern European styles and movements › Modern European fine arts styles and movements › Magic Realism. AAT 300021351.', '300021351'),
  ('culture.styles.modern_european.fine_arts.musicalist', 'Musicalism', 'European avant-garde doctrine or school of art that existed between 1932 and ca. 1960. AAT 300457790.', '300457790'),
  ('culture.styles.modern_european.fine_arts.nabi', 'Nabi', 'Describes the style of a group of young painters who met at the Académie Julian in 1888 to form a brotherhood called the "Nabis". Also called Les Nabis, the Nabis. AAT 300440784.', '300440784'),
  ('culture.styles.modern_european.fine_arts.neo_florentine', 'Neo-Florentine', 'Art & architecture styles › Modern European styles and movements › Modern European fine arts styles and movements › Neo-Florentine. AAT 300122744.', '300122744'),
  ('culture.styles.modern_european.fine_arts.neo_idealist', 'Neo-Idealism', 'An anti-modernist movement in early to mid-20th century Germany that focused on an idealized German past. AAT 300265222.', '300265222'),
  ('culture.styles.modern_european.fine_arts.neo_realisme', 'Néo-Réalisme', 'A movement among French painters of the 1920s and 1930s in reaction to modern movements such as Surrealism and Cubism. Also called Neo-Realism. AAT 300264659.', '300264659'),
  ('culture.styles.modern_european.fine_arts.new_vision', 'New Vision', 'Refers to the aesthetic theories of Hungarian artist László Moholy-Nagy, which he explored predominantly through photography. AAT 300263414.', '300263414'),
  ('culture.styles.modern_european.fine_arts.norwich_school', 'Norwich School', 'Style of the 19th century provincial art movement in Britain. AAT 300440787.', '300440787'),
  ('culture.styles.modern_european.fine_arts.pictorialist', 'Pictorialism', 'The 19th-century movement in photography. Also called Pictorial. AAT 300111559.', '300111559'),
  ('culture.styles.modern_european.fine_arts.post_expressionist', 'Post Expressionism', 'A variety of styles and movements after WWI that were influenced by expressionism but rejected its aesthetic. AAT 300440788.', '300440788'),
  ('culture.styles.modern_european.fine_arts.post_impressionist', 'Post-Impressionism', 'Refers to a movement of Western art that existed from the late nineteenth century through the early twentieth century. Also called Postimpressionism, Postimpressionist. AAT 300021508.', '300021508'),
  ('culture.styles.modern_european.fine_arts.realist', 'Realism', 'Refers to the style of Western art that existed from the mid- through the late nineteenth century and developed in reaction to the Romantic style. AAT 300172861.', '300172861'),
  ('culture.styles.modern_european.fine_arts.return_to_order', 'Return to order', 'A post-World War I conservative cultural movement in France and elsewhere in Europe, defined by a resurgence of classicism. AAT 300458737.', '300458737'),
  ('culture.styles.modern_european.fine_arts.simultanism', 'Simultanism', 'Term invented by Robert Delaunay to describe the abstract painting style developed by him and Sonia Delaunay, characterized by interlocking planes of color. AAT 300455820.', '300455820'),
  ('culture.styles.modern_european.fine_arts.straight', 'Straight', 'A photography style of the early 20th century. Also called Straight photography. AAT 300134613.', '300134613'),
  ('culture.styles.modern_european.fine_arts.surrealist', 'Surrealism', 'Refers to the international intellectual movement centered mainly in Paris from the 1920s to the late 1940s. Also called Superrealism. AAT 300021512.', '300021512'),
  ('culture.styles.modern_european.fine_arts.symbolist', 'Symbolism', 'Refers to the international intellectual movement that was first applied to literature in the late 19th century, spreading to painting and theater. Also called Symbolist movement. AAT 300021514.', '300021514'),
  ('culture.styles.modern_european.fine_arts.unanimist', 'Unanimism', 'Refers to the French artistic and literary movement founded in 1908 by Jules Romains. Also called Unanimisme. AAT 300122717.', '300122717'),
  ('culture.styles.modern_european.regional.austrian', 'Modern Austrian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Austrian styles and movements. AAT 300021176.', '300021176'),
  ('culture.styles.modern_european.regional.belgian', 'Modern Belgian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Belgian styles and movements. AAT 300378930.', '300378930'),
  ('culture.styles.modern_european.regional.british', 'Modern British styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern British styles and movements. AAT 300021191.', '300021191'),
  ('culture.styles.modern_european.regional.croatian', 'Modern Croatian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Croatian styles and movements. AAT 300403930.', '300403930'),
  ('culture.styles.modern_european.regional.czech', 'Modern Czech styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Czech styles and movements. AAT 300265836.', '300265836'),
  ('culture.styles.modern_european.regional.danish', 'Modern Danish styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Danish styles and movements. AAT 300021253.', '300021253'),
  ('culture.styles.modern_european.regional.dutch', 'Modern Dutch styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Dutch styles and movements. AAT 300021258.', '300021258'),
  ('culture.styles.modern_european.regional.finnish', 'Modern Finnish styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Finnish styles and movements. AAT 300403921.', '300403921'),
  ('culture.styles.modern_european.regional.french', 'Modern French styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern French styles and movements. AAT 300021265.', '300021265'),
  ('culture.styles.modern_european.regional.german', 'Modern German styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern German styles and movements. AAT 300021311.', '300021311'),
  ('culture.styles.modern_european.regional.hungarian', 'Modern Hungarian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Hungarian styles and movements. AAT 300403924.', '300403924'),
  ('culture.styles.modern_european.regional.italian', 'Modern Italian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Italian styles and movements. AAT 300021360.', '300021360'),
  ('culture.styles.modern_european.regional.norwegian', 'Modern Norwegian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Norwegian styles and movements. AAT 300403939.', '300403939'),
  ('culture.styles.modern_european.regional.polish', 'Modern Polish styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Polish styles and movements. AAT 300191864.', '300191864'),
  ('culture.styles.modern_european.regional.portuguese', 'Modern Portuguese styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Portuguese styles and movements. AAT 300393153.', '300393153'),
  ('culture.styles.modern_european.regional.russian', 'Modern Russian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Russian styles and movements. AAT 300021391.', '300021391'),
  ('culture.styles.modern_european.regional.scandinavian_modern', 'Scandinavian modern', 'Mid-20th century style of industrial and furniture design characterized by organic shapes, a lack of applied ornament, and extensive use of wood. Also called Scandinavian Design. AAT 300266638.', '300266638'),
  ('culture.styles.modern_european.regional.slovenian', 'Modern Slovenian styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Slovenian styles and movements. AAT 300403920.', '300403920'),
  ('culture.styles.modern_european.regional.spanish_fine_arts', 'Modern Spanish fine arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Spanish fine arts styles and movements. AAT 300122740.', '300122740'),
  ('culture.styles.modern_european.regional.swedish', 'Modern Swedish styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Swedish styles and movements. AAT 300403922.', '300403922'),
  ('culture.styles.modern_european.regional.swiss', 'Modern Swiss styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Swiss styles and movements. AAT 300403926.', '300403926'),
  ('culture.styles.modern_european.regional.yugoslav', 'Modern Yugoslav styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Yugoslav styles and movements. AAT 300192336.', '300192336'),
  ('culture.styles.modern_european.revival.assyrian_revival', 'Assyrian Revival', 'A style of the second half of the 19th century and early 20th inspired by Assyrian works of art, most specifically sculpture. AAT 300448613.', '300448613'),
  ('culture.styles.modern_european.revival.baroque_revival', 'Baroque Revival', 'Refers mainly to the architectural style in Europe, especially in large public buildings, from the end of the 19th century until approximately World War I. Also called English Renaissance, High Edwardian Baroque. AAT 300021444.', '300021444'),
  ('culture.styles.modern_european.revival.byzantine_revival', 'Byzantine Revival', 'Refers mainly to the style in architecture and decorative arts in Europe and the United States during the second half of the 19th century and the beginning of the 20th century. Also called Neo-Byzantine. AAT 300021446.', '300021446'),
  ('culture.styles.modern_european.revival.classical_revival', 'Classical Revival', 'Refers to late 18th- to early 20th-century architecture and ornament based relatively closely on ancient classical forms. Also called Classic Revival, Neo-Classical Revival. AAT 300108149.', '300108149'),
  ('culture.styles.modern_european.revival.egyptian_revival', 'Egyptian Revival', 'Refers to the style in American and European architecture and decorative arts dating between the late 18th and early 19th centuries and influenced by publications about Egypt. Also called Egyptian Style, Egyptian Taste, Neo-Egyptian. AAT 300021448.', '300021448'),
  ('culture.styles.modern_european.revival.etruscan_style', 'Etruscan Style', 'Refers to the style in European interior design, furniture, and ceramics in the late 18th century. AAT 300021450.', '300021450'),
  ('culture.styles.modern_european.revival.gothic_revival', 'Gothic Revival', 'Style in architecture and decorative arts characterized by a return to rosettes, pinnacles, tracery, foils, and polychrome effects inspired by Gothic architecture. Also called Neo-Gothic. AAT 300021452.', '300021452'),
  ('culture.styles.modern_european.revival.greek_revival', 'Greek Revival', 'Refers to the style of architecture and decorative arts in Europe and the United States from the 1750s inspired by ancient Greek architecture. Also called Neo-Greek. AAT 300021456.', '300021456'),
  ('culture.styles.modern_european.revival.historicism', 'Historicism', 'Refers to the revival of historical styles, often in eclectic combination, in 19th-century architecture after Neo-Classicism beginning in the 1820s. Also called Eclecticism. AAT 300391347.', '300391347'),
  ('culture.styles.modern_european.revival.moorish_revival', 'Moorish Revival', 'Refers to the style in 19th-century European architecture and decorative arts characterized by Hispano-Moresque forms and motifs such as honeycomb vaulting. AAT 300198720.', '300198720'),
  ('culture.styles.modern_european.revival.mudejar_revival', 'Mudéjar revival', 'Style of architecture and the decorative arts employed by some artists in Spain and its colonies in the 19th century. AAT 300444316.', '300444316'),
  ('culture.styles.modern_european.revival.neo_russian_style', 'Neo-Russian Style', 'An architectural style evident in Russia from the late 19th century until 1917 that relies on old Russian decoration and spatial construction. Also called Russian revival, Russian Style. AAT 300265657.', '300265657'),
  ('culture.styles.modern_european.revival.pompeian_style', 'Pompeian Style', 'Refers to the style of European and American interior design and decorative arts inspired by the archaeological findings at Pompeii and Herculaneum in the mid-18th century. Also called Pompeiian Style. AAT 300021462.', '300021462'),
  ('culture.styles.modern_european.revival.renaissance_revival', 'Renaissance Revival', 'Refers to the style in 19th-century European and American architecture and decorative arts initially inspired by the Italian Renaissance. Also called Neo-Renaissance. AAT 300021464.', '300021464'),
  ('culture.styles.modern_european.revival.rococo_revival', 'Rococo Revival', 'Refers to the 19th century style originating in France and spreading to Europe, England, and the United States, that revived Rococo forms and motifs in interior design. Also called Old French, Neo-Rococo. AAT 300021466.', '300021466'),
  ('culture.styles.modern_european.revival.romanesque_revival', 'Romanesque Revival', 'Refers to the style in European and American architecture dating from the 1820s to the end of the 19th century. Also called Neo-Romanesque. AAT 300021467.', '300021467'),
  ('culture.styles.modern_european.revival.venetian_revival', 'Venetian Revival', 'General term for art and architecture inspired by Venetian styles, which encompass Byzantine, Venetian Renaissance, and Gothic elements. AAT 300444353.', '300444353'),
  ('culture.styles.modern_european.secession_movement.wiener_secession', 'Wiener Secession', 'Refers to the original movement of young Austrian artists led by Gustav Klimt, who broke with the Künstlerhaus in 1897. Also called Vienna Secession. AAT 300435340.', '300435340'),
  ('culture.styles.post_1945_fine_arts.abstract_expressionist.abstract_imagist', 'Abstract Imagist', 'Refers to certain Abstract Expressionist paintings. Also called Abstract Image. AAT 300112063.', '300112063'),
  ('culture.styles.post_1945_fine_arts.abstract_expressionist.action_painting', 'Action painting', 'Refers to the term applied to the work of Abstract Expressionist painters such as Jackson Pollock and Willem de Kooning. Also called Gestural painting. AAT 300112061.', '300112061'),
  ('culture.styles.post_1945_fine_arts.art_informel.tachiste', 'Tachiste', 'French painting similar to American Action Painting, including that of the late 1940s sometimes called Abstraction Lyrique. Also called Tachisme, Abstraction Lyrique, Tachism. AAT 300022105.', '300022105'),
  ('culture.styles.post_1945_fine_arts.conceptual.photoconceptualism', 'Photoconceptualism', 'Photography by conceptual artists from the 1960s onward. Also called Photoconceptualist. AAT 300265224.', '300265224'),
  ('culture.styles.post_1945_fine_arts.process_art.auto_destructive_art', 'Auto-destructive art', 'Art in which the process of destruction of objects or materials within the work is regarded as the work, especially work created in the 1960s. Also called Autodestructive art, Auto-Creative. AAT 300112718.', '300112718'),
  ('culture.styles.renaissance_baroque.baroque.early_baroque', 'Early Baroque', 'Refers generally to the beginning of the Baroque style and period, particularly the Italian Baroque from about 1585 to 1625. AAT 300021149.', '300021149'),
  ('culture.styles.renaissance_baroque.baroque.high_baroque', 'High Baroque', 'Refers generally to the fully developed Baroque style, particularly the Italian art and architecture that emerged in Rome around 1625 and lasted for half a century. AAT 300021150.', '300021150'),
  ('culture.styles.renaissance_baroque.baroque.late_baroque', 'Late Baroque', 'Refers generally to the final years of the Baroque style, from approximately 1675 to 1715. AAT 300021151.', '300021151'),
  ('culture.styles.renaissance_baroque.renaissance.early_renaissance', 'Early Renaissance', 'Refers to the early period of the Renaissance, when the style developed in Central Italy in the mid- to late fourteenth century and spread in the early to mid-15th century. Also called Quattrocento. AAT 300021141.', '300021141'),
  ('culture.styles.renaissance_baroque.renaissance.high_renaissance', 'High Renaissance', 'Refers to a period and style that developed primarily in the last decade of the fifteenth century in Florence and Rome, spreading elsewhere in Italy and to northern Europe. Also called Cinquecento. AAT 300021142.', '300021142'),
  ('culture.styles.renaissance_baroque.renaissance.late_renaissance', 'Late Renaissance', 'Refers to a period and style of the middle and later decades of the 16th century in Italy and northern Europe. AAT 300021143.', '300021143'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.architecture', 'Renaissance-Baroque architecture styles', 'Architecture styles belonging to Renaissance-Baroque cultures. Also called Renaissance-Baroque architecture style. AAT 300021158.', '300021158'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.caravaggism', 'Caravaggism', 'Style of painting that flourished in Italy and northern Europe for three decades after the death of Michelangelo Merisi da Caravaggio (1571-1610). Also called Caravaggesque. AAT 300386054.', '300386054'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts', 'Renaissance-Baroque decorative arts styles', 'Decorative arts styles belonging to Renaissance-Baroque cultures. Also called Renaissance-Baroque decorative arts style. AAT 300021164.', '300021164'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.mannerist', 'Mannerism', 'Refers to a style and a period in evidence approximately from the 1520s to 1590, developing chiefly in Rome and spreading elsewhere in Europe. AAT 300021144.', '300021144'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.northern_mannerist', 'Northern Mannerism', 'Style of Mannerism found in the visual arts north of the Alps in the 16th and early 17th centuries. AAT 300440786.', '300440786'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.proto_baroque', 'Proto-Baroque', 'Designating works which are in an early or undeveloped Baroque style. AAT 300112426.', '300112426'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional', 'Renaissance-Baroque regional styles', 'Regional styles belonging to Renaissance-Baroque cultures. Also called Renaissance-Baroque regional style. AAT 300112572.', '300112572'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.romanist', 'Romanism', 'Art & architecture styles › Renaissance-Baroque styles and periods › Renaissance-Baroque styles › Romanism. Also called Italianate, Italianist, Italianizing. AAT 300021059.', '300021059'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.school_of_fontainebleau', 'School of Fontainebleau', 'Styles and periods of art and architecture during the late Renaissance centred on the French royal Palace of Fontainebleau. Also called Fontainebleau school. AAT 300412187.', '300412187'),
  ('culture.styles.early_christian_byzantine.byzantine.early_byzantine.justinianic', 'Justinianic', 'Refers to the Early Byzantine period and style associated with the reign of the Byzantine Emperor Justinian I (527-565). Also called First Golden Age. AAT 300020663.', '300020663'),
  ('culture.styles.early_christian_byzantine.byzantine.early_byzantine.theodosian', 'Theodosian', 'Refers to the style and period in the eastern Roman Empire surrounding the rule of Theodosius I (379-395 CE) through that of his grandson Theodosius II (408-450 CE). AAT 300020661.', '300020661'),
  ('culture.styles.early_christian_byzantine.byzantine.late_byzantine.palaeologan', 'Palaeologan', 'Refers to the revival of the Byzantine style in Byzantium and eastern Europe under the Palaeologue dynasty (1261-1453). Also called Third Golden Age, Byzantine Renaissance, Paleologue. AAT 300020701.', '300020701'),
  ('culture.styles.early_christian_byzantine.byzantine.middle_byzantine.comnenian', 'Comnenian', 'Refers to the Middle Byzantine style and period surrounding the Comneni dynasty (1081-1204) in the eastern Roman Empire. Also called Comnene, Komnenian. AAT 300020692.', '300020692'),
  ('culture.styles.early_christian_byzantine.byzantine.middle_byzantine.macedonian_renaissance', 'Macedonian Renaissance', 'Refers to the period and style that blossomed between the end of the Iconoclastic Controversy of 843 and the occupation of Constantinople by the Latins in 1204. AAT 300020688.', '300020688'),
  ('culture.styles.early_christian_byzantine.byzantine.regional.constantinopolitan', 'Constantinopolitan', 'Refers to the style of art that developed in the great Byzantine court at Constantinople. Also called Metropolitan. AAT 300020683.', '300020683'),
  ('culture.styles.early_christian_byzantine.byzantine.regional.italo_byzantine', 'Italo-Byzantine', 'Refers to the style and period that developed after the conquest of Constantinople by the armies of the Fourth Crusade in 1204 and lasted into the early 14th century. Also called Maniera greca. AAT 300020720.', '300020720'),
  ('culture.styles.early_christian_byzantine.byzantine.regional.russian', 'Russian Byzantine styles', 'Styles belonging to Russian Byzantine cultures. Also called Russian Byzantine style. AAT 300020732.', '300020732'),
  ('culture.styles.medieval.regional.migration_period.avar', 'Avar', 'Refers to the Migration period style associated with the Avars, who established an empire between the Adriatic and Baltic. Also called Avaric. AAT 300019461.', '300019461'),
  ('culture.styles.medieval.regional.migration_period.germanic', 'Germanic', 'Refers to the style and period associated with the Indo-European speakers of Germanic languages. AAT 300019487.', '300019487'),
  ('culture.styles.medieval.regional.migration_period.polychrome_style', 'Polychrome Style', 'Designates work of Migration period peoples, characterized by inlays of multicolored stones, usually in gold. Also called Gem Style. AAT 300019455.', '300019455'),
  ('culture.styles.medieval.regional.northern_european.anglo_norman', 'Anglo-Norman', 'Refers to the period and style associated with the Norman Conquest of Britain in 1066 and the spread of Norman tastes through the English, Welsh, and Irish aristocracy. AAT 300021006.', '300021006'),
  ('culture.styles.medieval.regional.northern_european.british_isles', 'British Isles Medieval styles', 'Styles belonging to British Isles Medieval cultures. Also called British Isles Medieval style. AAT 300020794.', '300020794'),
  ('culture.styles.medieval.regional.northern_european.carolingian', 'Carolingian styles', 'Styles belonging to Carolingian cultures. Also called Carolingian style. AAT 300106975.', '300106975'),
  ('culture.styles.medieval.regional.northern_european.channel_style', 'Channel Style', 'Refers to a distinctive style that developed in Flanders and northern France, beginning in the late tenth century and lasting through the 12th century. Also called Channel School. AAT 300021013.', '300021013'),
  ('culture.styles.medieval.regional.northern_european.danubian', 'Danubian', 'Refers to the styles and cultures of the Medieval principalities that developed along the Danube river in central Europe. AAT 300019335.', '300019335'),
  ('culture.styles.medieval.regional.northern_european.franco_flemish', 'Franco-Flemish', 'Refers to the style and culture evident in areas held by Burgundian rulers of Flanders, particularly during the 14th and 15th centuries. AAT 300020835.', '300020835'),
  ('culture.styles.medieval.regional.northern_european.french', 'French Medieval styles', 'Styles belonging to French Medieval cultures. Also called French Medieval style. AAT 300020854.', '300020854'),
  ('culture.styles.medieval.regional.northern_european.german', 'German Medieval styles', 'Styles belonging to German Medieval cultures. Also called German Medieval style. AAT 300020886.', '300020886'),
  ('culture.styles.medieval.regional.northern_european.mosan', 'Mosan', 'Refers to a Romanesque school of manuscript illumination, enamelwork and metalwork that flourished in the Meuse Valley from the late 11th to the early 13th century. Also called Mosan School. AAT 300264268.', '300264268'),
  ('culture.styles.medieval.regional.northern_european.scandinavian', 'Scandinavian Medieval styles', 'Styles belonging to Scandinavian Medieval cultures. Also called Scandinavian Medieval style. AAT 300020936.', '300020936'),
  ('culture.styles.medieval.regional.northern_european.zackenstil', 'Zackenstil', 'Refers to a style that was predominant in German-speaking regions in the 13th century in panel painting, wall painting, stained glass, and manuscript illumination. AAT 300262981.', '300262981'),
  ('culture.styles.medieval.regional.southern_european.first_romanesque', 'First Romanesque', 'Refers to a style of architecture and art evident in Catalonia and Lombardy beginning in the tenth century. Also called le premier art roman, Lombard-Catalan, premier art roman. AAT 300020770.', '300020770'),
  ('culture.styles.medieval.regional.southern_european.italian', 'Italian Medieval styles', 'Styles belonging to Italian Medieval cultures. Also called Italian Medieval style. AAT 300106965.', '300106965'),
  ('culture.styles.medieval.regional.southern_european.portuguese', 'Portuguese Medieval styles', 'Styles belonging to Portuguese Medieval cultures. Also called Portuguese Medieval style. AAT 300020934.', '300020934'),
  ('culture.styles.medieval.regional.southern_european.spanish', 'Spanish Medieval styles', 'Styles belonging to Spanish Medieval cultures. Also called Spanish Medieval style. AAT 300020940.', '300020940'),
  ('culture.styles.modern_european.decorative_arts.ceramics.abbotsford', 'Abbotsford', 'Style in imitation of Wemyss ware produced by the Kirkcaldy pottery of David Methven and Sons. AAT 300265225.', '300265225'),
  ('culture.styles.modern_european.decorative_arts.ceramics.armorial', 'Armorial', 'Porcelain style focused on heraldic motifs, particularly the style of the 18th century produced in China for European export. AAT 300021425.', '300021425'),
  ('culture.styles.modern_european.decorative_arts.ceramics.buen_retiro', 'Buen Retiro', 'Refers to the style of soft-paste porcelain first produced at the Real Fábrica del Buen Retiro near Madrid in 1759. AAT 300380336.', '300380336'),
  ('culture.styles.modern_european.decorative_arts.ceramics.capodimonte', 'Capodimonte', 'Refers to the style of soft-paste porcelain first produced by the factory at the Palazzo di Capodimonte, Naples, in 1743. AAT 300380320.', '300380320'),
  ('culture.styles.modern_european.decorative_arts.ceramics.capodimonte_ware', 'Capodimonte ware', 'Soft-paste porcelain ware first produced by the factory at the Palazzo di Capodimonte in 1743. Also called Capodimonte porcelain. AAT 300387411.', '300387411'),
  ('culture.styles.modern_european.decorative_arts.ceramics.rockingham', 'Rockingham', 'Styles of pottery made by the Rockingham Ceramic Factory (1745-1842) at Swinton in southern Yorkshire. AAT 300265601.', '300265601'),
  ('culture.styles.modern_european.decorative_arts.ceramics.wemyss', 'Wemyss', 'Refers to a style of 19th- and early 20th-century Scottish pottery characterized by flowers, fruit, or animals. AAT 300254018.', '300254018'),
  ('culture.styles.modern_european.fine_arts.abstract.nonobjective', 'Nonobjectivism', 'Refers specifically to Abstract art in which the forms have had no beginning or reference to nature. Also called Non-objective, Non-objectivism. AAT 300134149.', '300134149'),
  ('culture.styles.modern_european.fine_arts.cubist.analytical_cubist', 'Analytical Cubism', 'Refers to the phase of Cubism that focuses primarily on the depiction of different aspects of the same object simultaneously. Also called Analytic Cubist. AAT 300133798.', '300133798'),
  ('culture.styles.modern_european.fine_arts.cubist.rondo_cubist', 'Rondo-Cubism', 'Style that is specifically Czech, with folk elements. Also called Czech Art Deco. AAT 300443478.', '300443478'),
  ('culture.styles.modern_european.fine_arts.cubist.synthetic_cubist', 'Synthetic Cubism', 'Refers to the phase of Cubism that emerged in 1912 and is characterized by the use of collage and the addition of materials such as sand to pigment. Also called Collage Cubism, Collage Cubist. AAT 300021499.', '300021499'),
  ('culture.styles.modern_european.fine_arts.surrealist.abstract_surrealist', 'Abstract Surrealism', 'A mid-1940s precursor of Abstract Expressionism, a transitional synthesis of various forms of abstraction with Surrealist automatism. AAT 300410313.', '300410313'),
  ('culture.styles.modern_european.fine_arts.symbolist.rosicrucian', 'Rosicrucianism', 'Branch of the Symbolist movement and style inspired by and borrowing from Rosicrucian philosophy, traditions, and allegory. AAT 300122745.', '300122745'),
  ('culture.styles.modern_european.regional.austrian.sezessionstil', 'Sezessionstil', 'Austrian variation of Art Nouveau, derived from architect Joseph Olbrich''s exhibition hall for the Wiener Sezession. AAT 300021177.', '300021177'),
  ('culture.styles.modern_european.regional.belgian.la_libre_esthetique', 'La Libre Esthétique', 'A Belgian variation of Art Nouveau, so-called after the exhibition of the same name, organized by lawyer Octave Maus in 1893. AAT 300378907.', '300378907'),
  ('culture.styles.modern_european.regional.belgian.le_style_des_vingt', 'Le Style des Vingt', 'A Belgian variation of Art Nouveau named after the avant-garde group "Les XX" or "Les Vingt". AAT 300378906.', '300378906'),
  ('culture.styles.modern_european.regional.belgian.luminist', 'Luminism', 'Belgian art movement in painting associated with the group ''Vie et Lumière'' formed around the artist Emile Claus in 1904. AAT 300411669.', '300411669'),
  ('culture.styles.modern_european.regional.belgian.paling_stijl', 'Paling stijl', 'Refers to a Belgian variation of Art Nouveau, meaning "eel style." AAT 300375735.', '300375735'),
  ('culture.styles.modern_european.regional.belgian.style_coup_de_fouet', 'Style coup de fouet', 'Refers to a Belgian variation of Art Nouveau, so named for the "coup de fouet" or whiplash motif common to the style. AAT 300378908.', '300378908'),
  ('culture.styles.modern_european.regional.british.adam_style', 'Adam Style', 'Refers to the style identified with Scottish-born architect Robert Adam (1728-1792), prevalent in Great Britain from 1760-1790. Also called Adamesque, Adam-style. AAT 300021201.', '300021201'),
  ('culture.styles.modern_european.regional.british.aesthetic_movement', 'Aesthetic Movement', 'Refers to a British and American movement influencing fine and decorative art and architecture in the 1870s and 1880s. Also called Aestheticism. AAT 300018124.', '300018124'),
  ('culture.styles.modern_european.regional.british.architecture', 'Modern British architecture styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern British styles and movements › Modern British architecture styles and movements. AAT 300021207.', '300021207'),
  ('culture.styles.modern_european.regional.british.arts_and_crafts', 'Arts and Crafts', 'An aesthetic and social movement of the late 19th century that originated in England and spread to the United States, Germany, and Northern Europe. Also called Arts and Crafts Movement, Arts & Crafts Movement. AAT 300266319.', '300266319'),
  ('culture.styles.modern_european.regional.british.country_house_style', 'Country House Style', 'Style of interior architecture and design using elements of English country houses. Also called English Country House Style. AAT 300444309.', '300444309'),
  ('culture.styles.modern_european.regional.british.decorative_arts', 'Modern British decorative arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern British styles and movements › Modern British decorative arts styles and movements. AAT 300021213.', '300021213'),
  ('culture.styles.modern_european.regional.british.fine_arts', 'Modern British fine arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern British styles and movements › Modern British fine arts styles and movements. AAT 300021221.', '300021221'),
  ('culture.styles.modern_european.regional.british.glasgow_style', 'Glasgow style', 'Scottish variation of Art Nouveau that originated at the Glasgow School of Art. AAT 300375728.', '300375728'),
  ('culture.styles.modern_european.regional.british.proto_art_nouveau', 'Proto-Art Nouveau', 'English aesthetic style from the 1870s and 1880s, developing as an offshoot of the Arts and Crafts Movement. AAT 300403932.', '300403932'),
  ('culture.styles.modern_european.regional.british.quaint_style', 'Quaint Style', 'English variation of Art Nouveau, used primarily to describe mass-produced goods of many types, typically furniture. AAT 300378910.', '300378910'),
  ('culture.styles.modern_european.regional.british.queen_anne_revival', 'Queen Anne Revival', 'Refers to the style of domestic architecture but also of furniture in England and the United States in the late 19th century. Also called Queen Anne Style. AAT 300021197.', '300021197'),
  ('culture.styles.modern_european.regional.british.reign', 'Modern British styles by reign', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern British styles and movements › Modern British styles by reign. AAT 300021229.', '300021229'),
  ('culture.styles.modern_european.regional.british.revival', 'Modern British revival styles', 'Modern revival styles belonging to British cultures. Also called modern British revival style. AAT 300021193.', '300021193'),
  ('culture.styles.modern_european.regional.british.yachting_style', 'Yachting Style', 'Pejorative term for Art Nouveau coined by author Edmond de Goncourt after seeing an exhibition of Belgian artist Henry van de Velde. AAT 300375737.', '300375737'),
  ('culture.styles.modern_european.regional.croatian.secesija', 'Secesija', 'Variation of Art Nouveau found in Croatia. AAT 300403929.', '300403929'),
  ('culture.styles.modern_european.regional.czech.architecture', 'Modern Czech architecture styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Czech styles and movements › Modern Czech architecture styles and movements. AAT 300265837.', '300265837'),
  ('culture.styles.modern_european.regional.czech.poetist', 'Poetism', 'Czech avant-garde movement of the 1920s, spearheaded by Karel Teige and the group Devětsil. Also called Czech Poetism. AAT 300266332.', '300266332'),
  ('culture.styles.modern_european.regional.danish.hellenerne', 'Hellenerne', 'Artistic movement that flourished in Denmark beginning in the 1890s, as a self-styled reaction to what was perceived as pessimism and a world in decline. Also called Hellenists''. AAT 300021257.', '300021257'),
  ('culture.styles.modern_european.regional.dutch.constructive_decorative_style', 'Constructive-Decorative Style', 'Dutch style characterized by construction as the basis for the form of an object, with ornament also playing an important role. AAT 300403942.', '300403942'),
  ('culture.styles.modern_european.regional.dutch.constructive_style', 'Constructive Style', 'Dutch variations of Art Nouveau that stress form based on function, construction and material. AAT 300403943.', '300403943'),
  ('culture.styles.modern_european.regional.dutch.de_stijl', 'De Stijl', 'Refers to the Dutch artistic movement and periodical of the same name, founded by Theo van Doesburg in 1917 and lasting until the early 1930s. AAT 300021259.', '300021259'),
  ('culture.styles.modern_european.regional.dutch.decorative_arts', 'Modern Dutch decorative arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Dutch styles and movements › Modern Dutch decorative arts styles and movements. AAT 300180698.', '300180698'),
  ('culture.styles.modern_european.regional.dutch.decorative_style', 'Decorative Style', 'Term for variations of Art Nouveau in the Netherlands. Also called Slaolie style. AAT 300403941.', '300403941'),
  ('culture.styles.modern_european.regional.dutch.elementarist', 'Elementarism', 'Refers to the Dutch style that grew out of the theories of the De Stijl movement in the 1920s. AAT 300021261.', '300021261'),
  ('culture.styles.modern_european.regional.dutch.neo_plastic', 'Neo-Plasticism', 'Refers to the Dutch artistic style that grew out of the theories of the De Stijl movement and was named by Piet Mondrian in 1919. Also called Plastic, Neoplasticism. AAT 300021262.', '300021262'),
  ('culture.styles.modern_european.regional.dutch.nieuwe_kunst', 'Nieuwe Kunst', 'A Dutch variation of Art Nouveau, meaning "new art". AAT 300378891.', '300378891'),
  ('culture.styles.modern_european.regional.finnish.jugend', 'Jugend', 'Finnish variations of Jugend and Art Nouveau, including elements of Finnish nature and national culture. AAT 300403935.', '300403935'),
  ('culture.styles.modern_european.regional.french.decorative_arts', 'Modern French decorative arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern French styles and movements › Modern French decorative arts styles and movements. AAT 300021288.', '300021288'),
  ('culture.styles.modern_european.regional.french.fine_arts', 'Modern French fine arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern French styles and movements › Modern French fine arts styles and movements. AAT 300021293.', '300021293'),
  ('culture.styles.modern_european.regional.french.gout_grec', 'Goût grec', 'Refers to the early phase of French Neoclassicism that dates from the mid 1750s to the late 1760s and that stood in contrast to the Rococo style. Also called Greek Taste, le goût grec. AAT 300021289.', '300021289'),
  ('culture.styles.modern_european.regional.french.neo_grec', 'Néo-Grec', 'Refers to the French style in architecture and decorative arts during the Second Empire from 1852 to 1871, characterized by polychromy and Greek decorative motifs. Also called Néo-Grecque. AAT 300112469.', '300112469'),
  ('culture.styles.modern_european.regional.french.reign', 'Modern French styles by reign', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern French styles and movements › Modern French styles by reign. AAT 300021266.', '300021266'),
  ('culture.styles.modern_european.regional.french.troubadour', 'Troubadour', 'Refers to the style of architecture, decorative arts, and painting in France from the late 18th to the early 19th centuries. Also called Cathedral Style. AAT 300021291.', '300021291'),
  ('culture.styles.modern_european.regional.german.architecture', 'Modern German architecture styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern German styles and movements › Modern German architecture styles and movements. AAT 300021327.', '300021327'),
  ('culture.styles.modern_european.regional.german.bandwurmstil', 'Bandwurmstil', 'German term for a variation of Art Nouveau that developed in Belgium, meaning "tape worm style". Also called belgischer Bandwurm. AAT 300375733.', '300375733'),
  ('culture.styles.modern_european.regional.german.bauhaus', 'Bauhaus', 'Refers to the German School of art, design, and architecture active in Weimar from 1919 to 1925, in Dessau from 1925 to 1932, and in Berlin from 1932 to 1933. AAT 300021432.', '300021432'),
  ('culture.styles.modern_european.regional.german.belgische', 'Belgische', 'Refers to a German variation of Art Nouveau, named after the work of Belgian artist Henry van de Velde. Also called Belgische Stil. AAT 300378902.', '300378902'),
  ('culture.styles.modern_european.regional.german.ceramics', 'Modern German ceramics styles', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern German styles and movements › Modern German ceramics styles. Also called modern German ceramics style. AAT 300108114.', '300108114'),
  ('culture.styles.modern_european.regional.german.fine_arts', 'Modern German fine arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern German styles and movements › Modern German fine arts styles and movements. AAT 300021331.', '300021331'),
  ('culture.styles.modern_european.regional.german.jugendstil', 'Jugendstil', 'Refers to the German and Austrian variation of Art Nouveau, named after the magazine "Jugend" that had been published in Munich since 1896. AAT 300021313.', '300021313'),
  ('culture.styles.modern_european.regional.german.schnorkelstil', 'Schnörkelstil', 'German term used to refer to the work of Belgian artist Henry van de Velde, meaning "scroll style" or "flourish style". Also called Schnorkelstil. AAT 300375734.', '300375734'),
  ('culture.styles.modern_european.regional.german.studio_stil', 'Studio-Stil', 'German term for a variation of Art Nouveau. Also called Studio-Style. AAT 300375742.', '300375742'),
  ('culture.styles.modern_european.regional.german.veldesche', 'Veldesche', 'Refers to a German variation of Art Nouveau, named after the work of Belgian artist Henry van de Velde. Also called Veldescher Stil. AAT 300375732.', '300375732'),
  ('culture.styles.modern_european.regional.german.zopfstil', 'Zopfstil', 'Refers to the German late-18th-century Antique Revival style, known in German as the "pig-tail style." Also called Pigtail and Periwig Style. AAT 300108106.', '300108106'),
  ('culture.styles.modern_european.regional.hungarian.szecesszio', 'Szecesszió', 'A Hungarian variation of Art Nouveau. AAT 300403925.', '300403925'),
  ('culture.styles.modern_european.regional.italian.architecture', 'Modern Italian architecture styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Italian styles and movements › Modern Italian architecture styles and movements. AAT 300021366.', '300021366'),
  ('culture.styles.modern_european.regional.italian.arte_nuova', 'Arte Nuova', 'Italian variation of Art Nouveau, as seen most prominently in architecture. AAT 300378904.', '300378904'),
  ('culture.styles.modern_european.regional.italian.decorative_arts', 'Modern Italian decorative arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Italian styles and movements › Modern Italian decorative arts styles and movements. AAT 300021370.', '300021370'),
  ('culture.styles.modern_european.regional.italian.fine_arts', 'Modern Italian fine arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Italian styles and movements › Modern Italian fine arts styles and movements. AAT 300021372.', '300021372'),
  ('culture.styles.modern_european.regional.italian.futurist', 'Futurism', 'Refers to the literary and artistic movement centered in Italy that emphasized speed, dynamism, energy and a rejection of the past, which began with the writings of Filippo Tommaso Marinetti. AAT 300021374.', '300021374'),
  ('culture.styles.modern_european.regional.italian.stile_liberty', 'Stile Liberty', 'Refers to the style and movement that was an Italian interpretation of Art Nouveau architectural principles. Also called Liberty, Liberty Style, Neo-Liberty. AAT 300021362.', '300021362'),
  ('culture.styles.modern_european.regional.italian.strapaese', 'Strapaese', 'Cultural movement of Italy from the 1920s to the 1940s, which rejected modernist tendencies in art and literature. AAT 300266308.', '300266308'),
  ('culture.styles.modern_european.regional.norwegian.dragestil', 'Dragestil', 'Norwegian national style inspired by 11th-century Norse ornamentation and stave churches in Norway. AAT 300403940.', '300403940'),
  ('culture.styles.modern_european.regional.polish.formist', 'Formism', 'Refers to the style and movement associated with a group of Polish painters and sculptors that worked between 1917 and 1922. AAT 300178877.', '300178877'),
  ('culture.styles.modern_european.regional.polish.modernizm', 'Modernizm', 'A Polish variation of Art Nouveau. AAT 300403933.', '300403933'),
  ('culture.styles.modern_european.regional.polish.rhythmist', 'Rhythmism', 'Style focusing on artistic iconoclasm and the breaking down of the traditional boundaries of academicians, abandoning realism. AAT 300179500.', '300179500'),
  ('culture.styles.modern_european.regional.polish.young_poland', 'Young Poland', 'Art Nouveau movement in Poland including the visual arts, literature, and music. AAT 300266311.', '300266311'),
  ('culture.styles.modern_european.regional.polish.zakopane_style', 'Zakopane Style', 'National Polish style of art and design, inspired by vernacular folk art forms, techniques, and motifs. AAT 300403923.', '300403923'),
  ('culture.styles.modern_european.regional.polish.zonist', 'Zonism', 'Refers to the style and movement founded by Leon Chwistek in the 1920s after the disintegration of the Formists. Also called Strefizm. AAT 300122751.', '300122751'),
  ('culture.styles.modern_european.regional.portuguese.arte_nova', 'Arte Nova', 'Portuguese expression of the Art Nouveau movement. AAT 300393154.', '300393154'),
  ('culture.styles.modern_european.regional.russian.fine_arts', 'Modern Russian fine arts styles and movements', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Russian styles and movements › Modern Russian fine arts styles and movements. AAT 300111618.', '300111618'),
  ('culture.styles.modern_european.regional.russian.stil_modern', 'Stil'' Modern', 'Refers to a Russian variation of Art Nouveau that incorporated elements of that style with Russian folk art. AAT 300378919.', '300378919'),
  ('culture.styles.modern_european.regional.scandinavian_modern.new_empiricism', 'New Empiricism', 'Swedish and other Scandinavian architecture of the 1940s. Also called Scandinavian Empiricism. AAT 300444404.', '300444404'),
  ('culture.styles.modern_european.regional.slovenian.secesija', 'Secesija', 'Variation of Art Nouveau found in Slovenia. AAT 300403928.', '300403928'),
  ('culture.styles.modern_european.regional.spanish_fine_arts.arte_joven', 'Arte Joven', 'Refers to a Spanish variation of Art Nouveau, based on the work of a group of modernist writers and artists from Madrid. Also called Arte Jóven. AAT 300375736.', '300375736'),
  ('culture.styles.modern_european.regional.spanish_fine_arts.modernisme', 'Modernisme', 'The variation of the Art Nouveau movement in Spain. Also called Modernismo, Catalan Modernisme. AAT 300312268.', '300312268'),
  ('culture.styles.modern_european.regional.spanish_fine_arts.ultraist', 'Ultraism', 'Refers to the movement and style of art based on the Spanish literary movement of the early 20th century adopted by writers such as Jorge Luis Borges. AAT 300145809.', '300145809'),
  ('culture.styles.modern_european.regional.spanish_fine_arts.vibrationist', 'Vibrationism', 'Refers to the style and movement in painting and set design conceived by Uruguayan-born painter Rafael Barradas as a reaction to Futurism. AAT 300122772.', '300122772'),
  ('culture.styles.modern_european.regional.swedish.jugend', 'Jugend', 'Swedish variation of Jugend and Art Nouveau, more restrained than elsewhere in Europe. AAT 300403936.', '300403936'),
  ('culture.styles.modern_european.regional.swedish.kontrajugend', 'Kontrajugend', 'Swedish variation of Art Nouveau that emphasized stricter and more geometric designs. AAT 300403934.', '300403934'),
  ('culture.styles.modern_european.regional.swiss.style_sapin', 'Style Sapin', 'Variation of Art Nouveau in Switzerland, relating to the pupils of Charles L''Eplattenier in La Chaux-de-Fonds. AAT 300403927.', '300403927'),
  ('culture.styles.modern_european.regional.yugoslav.zenitist', 'Zenitism', 'Styles originating in or expressing ideals supported by the post-World War I review "Zenit". AAT 300192337.', '300192337'),
  ('culture.styles.modern_european.revival.moorish_revival.neo_mudejar', 'Neo-Mudéjar', 'Moorish Revival architecture seen primarily on the Iberian Peninsula and in Ibero-America. AAT 300444951.', '300444951'),
  ('culture.styles.modern_european.revival.renaissance_revival.dutch_renaissance_revival', 'Dutch Renaissance Revival', 'Revival style recalling Dutch Renaissance architecture, flourishing particularly in North America in the 19th century. AAT 300444290.', '300444290'),
  ('culture.styles.modern_european.revival.renaissance_revival.early_renaissance_revival', 'Early Renaissance Revival', 'Architectural and other art styles in the 19th century, inspired by the early Renaissance of the early to mid-15th century. AAT 300444303.', '300444303'),
  ('culture.styles.modern_european.revival.renaissance_revival.french_renaissance_revival', 'French Renaissance Revival', 'Architectural and other art styles in the 19th century, inspired by the Renaissance in France. AAT 300444305.', '300444305'),
  ('culture.styles.modern_european.revival.romanesque_revival.norman_revival', 'Norman Revival', 'Refers to the 19th-century English architectural style based on Norman forms and motifs such as round arches, battlements, and barrel and groin vaults. Also called Neo-Norman. AAT 300021468.', '300021468'),
  ('culture.styles.renaissance_baroque.baroque.late_baroque.baroque_classicism', 'Baroque Classicism', 'Style identified retroactively to describe works of the late 17th and 18th centuries. AAT 300440775.', '300440775'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.architecture.palladian', 'Palladianism', 'Includes works influenced by the architectural style of Andrea Palladio. AAT 300021161.', '300021161'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.auricular', 'Auricular', 'Refers to a style that employs a particular type of ornament and was popular in 17th-century Europe. Also called Knorpelwork, Lobate. AAT 300021165.', '300021165'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.ceramics', 'Renaissance-Baroque ceramics styles', 'Art & architecture styles › Renaissance-Baroque styles and periods › Renaissance-Baroque styles › Renaissance-Baroque decorative arts styles › Renaissance-Baroque ceramics styles. Also called Renaissance-Baroque ceramics style. AAT 300021168.', '300021168'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.chinoiserie', 'Chinoiserie', 'European and American decorative arts and architectural style that reflects fanciful and poetic notions of China. Also called Anglo-Chinoise. AAT 300021167.', '300021167'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.glassware', 'Renaissance-Baroque glassware styles', 'Glassware styles belonging to Renaissance-Baroque cultures. Also called Renaissance-Baroque glassware style. AAT 300264852.', '300264852'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.rocaille', 'Rocaille', 'Refers generally to the bolder and more extravagant flights of Rococo style as applied to the decorative arts, deriving from ornate rockwork and shellwork. Also called Rocail. AAT 300132707.', '300132707'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british', 'British Renaissance-Baroque styles', 'Styles belonging to British Renaissance-Baroque cultures. Also called British Renaissance-Baroque style. AAT 300021034.', '300021034'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.eastern_european', 'Eastern European Renaissance-Baroque styles', 'Styles belonging to Eastern European Renaissance-Baroque cultures. Also called Eastern European Renaissance-Baroque style. AAT 300107026.', '300107026'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french', 'French Renaissance-Baroque styles', 'Styles belonging to French Renaissance-Baroque cultures. Also called French Renaissance-Baroque style. AAT 300021070.', '300021070'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german', 'German Renaissance-Baroque styles', 'Styles belonging to German Renaissance-Baroque cultures. Also called German Renaissance-Baroque style. AAT 300021096.', '300021096'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian', 'Italian Renaissance-Baroque styles', 'Styles belonging to Italian Renaissance-Baroque cultures. Also called Italian Renaissance-Baroque style. AAT 300021103.', '300021103'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish', 'Netherlandish Renaissance-Baroque styles', 'Styles belonging to Netherlandish Renaissance-Baroque cultures. Also called Netherlandish Renaissance-Baroque style. AAT 300021051.', '300021051'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.northern_renaissance', 'Northern Renaissance', 'Refers to the style of art and architecture resulting from the spread of the Renaissance from Italy into northern Europe in the late 15th century. AAT 300252246.', '300252246'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.portuguese', 'Portuguese Renaissance-Baroque styles', 'Styles belonging to Portuguese Renaissance-Baroque cultures. Also called Portuguese Renaissance-Baroque style. AAT 300107029.', '300107029'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish', 'Spanish Renaissance-Baroque styles', 'Styles belonging to Spanish Renaissance-Baroque cultures. Also called Spanish Renaissance-Baroque style. AAT 300021127.', '300021127'),
  ('culture.styles.early_christian_byzantine.byzantine.late_byzantine.palaeologan.early_palaeologan', 'Early Palaeologan', 'Refers to the style and period that developed beginning with the return of the emperor Michael VIII Palaeologus to Constantinople in 1261. Also called Early Paleologue. AAT 300020704.', '300020704'),
  ('culture.styles.early_christian_byzantine.byzantine.late_byzantine.palaeologan.high_palaeologan', 'High Palaeologan', 'Refers to the period and style associated with the latter part of the reign of the house of the Palaeologi, particularly in the late 13th and early 14th centuries. Also called High Paleologue. AAT 300132705.', '300132705'),
  ('culture.styles.early_christian_byzantine.byzantine.regional.russian.muscovite', 'Muscovite', 'Generally, the style and culture of Moscow or of the former principality of Muscovy. AAT 300020740.', '300020740'),
  ('culture.styles.early_christian_byzantine.byzantine.regional.russian.russo_byzantine', 'Russo-Byzantine', 'Refers to the architectural style that developed in Russia in the early to mid 19th century. AAT 300451599.', '300451599'),
  ('culture.styles.early_christian_byzantine.byzantine.regional.russian.vladimir_suzdalian', 'Vladimir-Suzdalian', 'Refers to the style of architecture and art that developed beginning in the late 12th century at Vladimir in the principality of Rostov-Suzdal. Also called Suzdalian. AAT 300020738.', '300020738'),
  ('culture.styles.medieval.regional.migration_period.germanic.merovingian', 'Merovingian', 'Refers to the culture, period, and style ushered in by the conquest of Gaul by Clovis of the Merovingian dynasty in 486 CE. AAT 300019512.', '300019512'),
  ('culture.styles.medieval.regional.migration_period.germanic.recceswinth_period', 'Recceswinth period', 'Period and culture under the rule of Recceswinth, Visigothic King of Hispania in the 7th century. AAT 300445004.', '300445004'),
  ('culture.styles.medieval.regional.northern_european.british_isles.anglo_saxon', 'Anglo-Saxon', 'Refers to the period and style associated with the conquest of much of the British Isles by Germanic Saxons and Angles, beginning with the invasions of the fifth and sixth centuries CE. AAT 300021024.', '300021024'),
  ('culture.styles.medieval.regional.northern_european.british_isles.anglo_scandinavian', 'Anglo-Scandinavian', 'Refers to any English-Viking cultural interaction during the middle ages. AAT 300380065.', '300380065'),
  ('culture.styles.medieval.regional.northern_european.british_isles.architecture', 'British Isles Medieval architecture styles', 'Architecture styles belonging to British Isles Medieval cultures. Also called British Isles Medieval architecture style. AAT 300020795.', '300020795'),
  ('culture.styles.medieval.regional.northern_european.british_isles.hiberno_norse', 'Hiberno-Norse', 'The culture of Vikings linked to the Gaelic-speaking areas of Ireland. AAT 300389880.', '300389880'),
  ('culture.styles.medieval.regional.northern_european.british_isles.hiberno_saxon', 'Hiberno-Saxon', 'Refers to the highly individualized style that developed in Ireland beginning in the seventh century, particularly in the monastic communities. AAT 300021025.', '300021025'),
  ('culture.styles.medieval.regional.northern_european.british_isles.insular', 'Insular', 'Refers to the style that developed in the British Isles after the relaxation of imperial Roman authority, generally from the fifth century CE. AAT 300021018.', '300021018'),
  ('culture.styles.medieval.regional.northern_european.british_isles.pictish', 'Pictish', 'Describes the art of the Picts, the inhabitants of what is now northern and eastern Scotland, between the Roman occupation and the 9th century. AAT 300264663.', '300264663'),
  ('culture.styles.medieval.regional.northern_european.british_isles.pottery', 'British Isles Medieval pottery styles', 'Pottery styles belonging to British Isles Medieval cultures. Also called British Isles Medieval pottery style. AAT 300112569.', '300112569'),
  ('culture.styles.medieval.regional.northern_european.british_isles.trewhiddle_style', 'Trewhiddle Style', 'Refers to the style of late Anglo-Saxon art that flourished during the ninth century and is named after the Trewhiddle Hoard from Cornwall, England. AAT 300263130.', '300263130'),
  ('culture.styles.medieval.regional.northern_european.carolingian.franco_saxon', 'Franco-Saxon', 'Refers to the style of art, particularly manuscript illuminations, that developed in the ninth century in northern French monasteries. AAT 300106976.', '300106976'),
  ('culture.styles.medieval.regional.northern_european.carolingian.reims_style', 'Reims Style', 'Refers to a style of art, particularly manuscript illumination, that developed in the early ninth century in the scriptoria of the archbishop Ebbo of Reims. Also called Reims, Rheims Style, Utrecht Psalter Style, Utrecht Style. AAT 300020978.', '300020978'),
  ('culture.styles.medieval.regional.northern_european.french.architecture', 'French Medieval architecture styles', 'Architecture styles belonging to French Medieval cultures. Also called French Medieval architecture style. AAT 300106959.', '300106959'),
  ('culture.styles.medieval.regional.northern_european.german.architecture', 'German Medieval architecture styles', 'Architecture styles belonging to German Medieval cultures. Also called German Medieval architecture style. AAT 300106963.', '300106963'),
  ('culture.styles.medieval.regional.northern_european.scandinavian.viking', 'Viking', 'Refers to the period, culture, and style of art produced between the later eighth century and early 12th century in Scandinavia and Scandinavian settlements overseas. AAT 300019558.', '300019558'),
  ('culture.styles.medieval.regional.southern_european.italian.pottery', 'Italian Medieval pottery styles', 'Pottery styles belonging to Italian Medieval cultures. Also called Italian Medieval pottery style. AAT 300106969.', '300106969'),
  ('culture.styles.medieval.regional.southern_european.portuguese.manueline', 'Manueline', 'Refers to the style of art and architecture that flourished in Portugal and her colonies, beginning in the late 14th century and lasting into the mid-16th century. Also called Manueline Style. AAT 300020935.', '300020935'),
  ('culture.styles.medieval.regional.southern_european.spanish.asturian', 'Asturian', 'Refers to the style and culture of the Asturias region of northern Spain, particularly of the Medieval eighth- and ninth-century kingdom. AAT 300266484.', '300266484'),
  ('culture.styles.medieval.regional.southern_european.spanish.hispano_flemish', 'Hispano-Flemish', 'Refers to the style of Spanish architecture, painting, and decoration associated with the reign of Isabella I at the end of the 15th century. AAT 300112472.', '300112472'),
  ('culture.styles.medieval.regional.southern_european.spanish.hispano_moresque', 'Hispano-Moresque', 'Refers to the style of architecture and decorative arts on the Iberian peninsula under Muslim rule, roughly between the eighth and the 15th centuries. Also called Hispano-Islamic. AAT 300021014.', '300021014'),
  ('culture.styles.medieval.regional.southern_european.spanish.isabelline', 'Isabelline', 'Refers to the style of artistic production in Spain and its colonies during the reign of Isabella I, from about 1480 to about 1510. AAT 300021133.', '300021133'),
  ('culture.styles.medieval.regional.southern_european.spanish.mozarabic', 'Mozarabic', 'Refers to the style of artistic production produced by Spanish Christians under Muslim rule from the ninth to the 11th centuries. AAT 300021017.', '300021017'),
  ('culture.styles.medieval.regional.southern_european.spanish.mudejar', 'Mudéjar', 'Refers to the style of architecture and decorative arts that developed in Spain and Portugal during the period when the Moors gradually lost control of the Iberian peninsula, roughly during the 12th to 15th centuries. Also called Mudéjare. AAT 300020944.', '300020944'),
  ('culture.styles.modern_european.regional.british.architecture.free_style', 'Free Style', 'Refers to the style in late-19th-century architecture in which Queen Anne and vernacular styles mixed freely with Classical and Gothic elements. Also called Free Eclecticism. AAT 300108204.', '300108204'),
  ('culture.styles.modern_european.regional.british.architecture.old_english', 'Old English', 'Refers to the style of English domestic architecture in the second half of the nineteenth century characterized by traditional English materials and forms such as mullioned windows, half-timbered walls and pitched roofs. Also called Neo-Vernacular, Vernacular Revival. AAT 300021212.', '300021212'),
  ('culture.styles.modern_european.regional.british.architecture.scottish_baronial', 'Scottish Baronial', 'Refers to a Scottish architectural style in the mid-nineteenth century that revived forms associated with the traditional Scottish tower house such as machicolations, conical roofs, turrets, bartisans, and battlements. Also called Baronial, Scottish Baronial Revival, Scotch Baronial. AAT 300021211.', '300021211'),
  ('culture.styles.modern_european.regional.british.decorative_arts.british_cottage_style', 'British Cottage Style', 'Style of furniture and interior design in 19th-century England, inspired by homey designs of the English countryside. AAT 300444308.', '300444308'),
  ('culture.styles.modern_european.regional.british.decorative_arts.ceramics', 'Modern British ceramics styles', 'Modern ceramics styles belonging to British cultures. Also called modern British ceramics style. AAT 300021226.', '300021226'),
  ('culture.styles.modern_european.regional.british.decorative_arts.chippendale', 'Chippendale', 'Refers to English furniture produced in 1750s and 1760s based on the designs of cabinetmaker Thomas Chippendale (1718-1779), characterized by openwork and ornamental carving in a mainly Rococo Style. Also called Director Style. AAT 300021214.', '300021214'),
  ('culture.styles.modern_european.regional.british.decorative_arts.hepplewhite', 'Hepplewhite', 'Refers to English and American furniture following the designs of English cabinetmaker and designer George Hepplewhite published posthumously in 1788. AAT 300021219.', '300021219'),
  ('culture.styles.modern_european.regional.british.decorative_arts.sheraton', 'Sheraton', 'Describes satinwood, mahogany, and painted furniture in England and the United States from 1790 to 1805 based on designs published by English cabinetmaker Thomas Sheraton (1751-1806). AAT 300021220.', '300021220'),
  ('culture.styles.modern_european.regional.british.fine_arts.new_sculpture_movement', 'New Sculpture Movement', 'Refers to the movement in British sculpture ca. 1880-1910. Also called New Sculpture. AAT 300021223.', '300021223'),
  ('culture.styles.modern_european.regional.british.fine_arts.newlyn_school', 'Newlyn School', 'Refers to the styles of a disparate group of landscape painters active from the early 1880s in and around the town of Newlyn, in Cornwall. AAT 300311386.', '300311386'),
  ('culture.styles.modern_european.regional.british.fine_arts.pre_raphaelite', 'Pre-Raphaelitism', 'Refers to the style in fine arts originating from the Pre-Raphaelite Brotherhood, a group of English artists active from 1848 to 1853. Also called Preraphaelitism. AAT 300021225.', '300021225'),
  ('culture.styles.modern_european.regional.british.fine_arts.st_ives_school', 'St Ives School', 'Refers to the styles of a disparate group of artists working around the coastal town of Saint Ives, Cornwall, England. Also called St. Ives School, Saint Ives School. AAT 300311354.', '300311354'),
  ('culture.styles.modern_european.regional.british.fine_arts.vorticist', 'Vorticism', 'Refers to the British literary and artistic movement founded in 1914 by Wyndham Lewis and members of the Rebel Art Centre. AAT 300021515.', '300021515'),
  ('culture.styles.modern_european.regional.british.reign.edwardian', 'Edwardian', 'Refers mainly to the style of architecture produced during the reign of Edward VII (1901-1910), though some authors date it from 1890. AAT 300021236.', '300021236'),
  ('culture.styles.modern_european.regional.british.reign.medieval_revival', 'Medieval Revival', 'Style of architecture and decorative arts that began in Britain in the 19th century, evolving into Victorian styles that incorporated Gothic elements. Also called Medievalism. AAT 300444317.', '300444317'),
  ('culture.styles.modern_european.regional.british.reign.regency', 'Regency', 'Refers to the style of architecture and decorative arts produced in England during the regency of George, Prince of Wales from 1811 to 1820 and the reign of George IV from 1820 to 1830. AAT 300021231.', '300021231'),
  ('culture.styles.modern_european.regional.british.reign.strawberry_hill_gothic', 'Strawberry Hill Gothic', 'European fantasy architectural style of the late 18th and early 19th century that references Gothic and Rococo. Also called Gothick. AAT 300444340.', '300444340'),
  ('culture.styles.modern_european.regional.british.reign.victorian', 'Victorian', 'Refers to the style of artistic production produced in Great Britain and its colonies from 1837 to 1901 during the reign of Queen Victoria. AAT 300021232.', '300021232'),
  ('culture.styles.modern_european.regional.british.revival.elizabethan_revival', 'Elizabethan Revival', 'Refers to the English style of architecture, interior design, and decorative arts from the 1830s to the 1860s, drawn from the Elizabethan period of the sixteenth century. AAT 300021194.', '300021194'),
  ('culture.styles.modern_european.regional.british.revival.georgian_revival', 'Georgian Revival', 'Refers to the late nineteenth and early twentieth century English style that revived the architectural forms and decorative motifs of the Georgian period from 1714 to 1830. Also called Neo-Georgian. AAT 300021195.', '300021195'),
  ('culture.styles.modern_european.regional.british.revival.jacobean_revival', 'Jacobean Revival', 'Refers to the style of British architecture, furniture, and decorative arts during the nineteenth and early twentieth centuries that revived forms from the Jacobean period of the 17th century. AAT 300021196.', '300021196'),
  ('culture.styles.modern_european.regional.british.revival.jacobethan', 'Jacobethan', 'Refers to the 19th century English revival style in architecture and decorative arts that combines characteristics of both the Elizabethan and Jacobean periods. Also called Jacobethan Revival. AAT 300108088.', '300108088'),
  ('culture.styles.modern_european.regional.british.revival.palladian_revival', 'Palladian Revival', 'Architectural movement and style which began in England ca. 1715, reviving the designs of Andrea Palladio. Also called Neo-Palladian, Palladianism. AAT 300385938.', '300385938'),
  ('culture.styles.modern_european.regional.british.revival.stuart_revival', 'Stuart Revival', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern British styles and movements › Modern British revival styles › Stuart Revival. AAT 300021470.', '300021470'),
  ('culture.styles.modern_european.regional.british.revival.tudor_revival', 'Tudor Revival', 'Refers to the style of English architecture and interior design in the first half of the 19th century and again in the early 20th. Also called Neo-Tudor, Tudorbethan, mock Tudor. AAT 300021199.', '300021199'),
  ('culture.styles.modern_european.regional.british.revival.victorian_revival', 'Victorian Revival', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern British styles and movements › Modern British revival styles › Victorian Revival. AAT 300021471.', '300021471'),
  ('culture.styles.modern_european.regional.czech.architecture.czech_cubism', 'Czech Cubism', 'A style of architecture that developed in Prague ca. 1912-1928, as influenced by Cubism. AAT 300265838.', '300265838'),
  ('culture.styles.modern_european.regional.dutch.decorative_arts.ceramics', 'Modern Dutch ceramics styles', 'Ceramics styles belonging to modern Dutch cultures. Also called modern Dutch ceramics style. AAT 300180699.', '300180699'),
  ('culture.styles.modern_european.regional.french.decorative_arts.ceramics', 'Modern French ceramics styles', 'Ceramics styles belonging to modern French cultures. Also called modern French ceramics style. AAT 300106332.', '300106332'),
  ('culture.styles.modern_european.regional.french.fine_arts.animalier', 'Animalier', 'Refers to the style associated with a group of mid-nineteenth century French sculptors who produced small scale representations of domestic and wild animals. Also called Animalier Sculpture. AAT 300021295.', '300021295'),
  ('culture.styles.modern_european.regional.french.fine_arts.cloisonnist', 'Cloisonnism', 'Refers to a style of painting identified with a group of French artists in the 1880s and characterized by bright flat color, strong blue or black contour lines, and minimal modeling. Also called Cloisonism, Cloisonnisme. AAT 300021297.', '300021297'),
  ('culture.styles.modern_european.regional.french.fine_arts.fauve', 'Fauvism', 'Refers to a style in painting identified with a group of young French artists from around 1898 to 1906 and characterized by bold bright colors, surface texture, and spontaneity. Also called Fauvist. AAT 300021300.', '300021300'),
  ('culture.styles.modern_european.regional.french.fine_arts.intimist', 'Intimism', 'Describes works depicting informal, intimate domestic scenes of everyday life produced in the 1890s in an Impressionist style, identified with Pierre Bonnard and Édouard Vuillard. Also called Intimisme. AAT 300021423.', '300021423'),
  ('culture.styles.modern_european.regional.french.fine_arts.modern_style', 'Modern Style', 'A variation of Art Nouveau based on French works and influenced by works of Edward Burne-Jones and William Morris. AAT 300375743.', '300375743'),
  ('culture.styles.modern_european.regional.french.fine_arts.neo_impressionist', 'Neo-Impressionism', 'Refers to an avant-garde European art movement and style that flourished from 1886 to 1906. Also called Neoimpressionist. AAT 300021505.', '300021505'),
  ('culture.styles.modern_european.regional.french.fine_arts.orphist', 'Orphism', 'Refers to an abstract style of European painting circa 1912 inspired by Cubism but demonstrating a greater interest in color and lyricism. Also called Orphisme, Orphic Cubism. AAT 300134101.', '300134101'),
  ('culture.styles.modern_european.regional.french.fine_arts.purist', 'Purism', 'Refers to the movement in European painting begun circa 1918 as a response to the decorative quality in Cubism and characterized by clear, delineated geometric forms. AAT 300122664.', '300122664'),
  ('culture.styles.modern_european.regional.french.fine_arts.style_1900', 'Style 1900', 'A French variation of Art Nouveau, particularly used to describe artistic trends in architecture, the applied arts, and decoration. Also called L''Art 1900. AAT 300378909.', '300378909'),
  ('culture.styles.modern_european.regional.french.fine_arts.style_guimard', 'Style Guimard', 'A variation of Art Nouveau in France, coined by architect Hector Guimard to describe his own style. AAT 300378903.', '300378903'),
  ('culture.styles.modern_european.regional.french.fine_arts.style_jules_verne', 'Style Jules Verne', 'Refers to a French variation of Art Nouveau, so named for the style''s imagery and emphasis on the fantastic as seen in the writings of Jules Verne. AAT 300378905.', '300378905'),
  ('culture.styles.modern_european.regional.french.fine_arts.style_metro', 'Style Métro', 'Refers to a French variation of Art Nouveau, named after the Paris Métro entrance structures designed by Hector Guimard. Also called le style Métro. AAT 300375730.', '300375730'),
  ('culture.styles.modern_european.regional.french.fine_arts.style_nouille', 'Style nouille', 'Refers to a French variation of Art Nouveau, literally meaning "noodle style," referring to the interlacing lines characteristic of its designs. AAT 300375729.', '300375729'),
  ('culture.styles.modern_european.regional.french.fine_arts.synthetist', 'Synthetism', 'Refers to the style of painting centered in Pont Aven between 1886 and 1890 whose proponents advocated the simplification of form and painting from memory. AAT 300021308.', '300021308'),
  ('culture.styles.modern_european.regional.french.reign.directoire', 'Directoire', 'Refers to the style of decorative arts and architecture during the Directoire period between 1795 and 1799. AAT 300021267.', '300021267'),
  ('culture.styles.modern_european.regional.french.reign.empire', 'Empire', 'Refers to the style in decorative arts, interior design, architecture, and dress which spread from France to other parts of Europe and the United States during and after the Napoleonic period. Also called First Empire, French Empire. AAT 300021269.', '300021269'),
  ('culture.styles.modern_european.regional.french.reign.louis_philippe', 'Louis Philippe', 'Refers to the style of decorative arts and architecture produced in France during the reign of King Louis Philippe from 1830 to 1848. Also called Louis-Philippe. AAT 300021278.', '300021278'),
  ('culture.styles.modern_european.regional.french.reign.louis_xvi', 'Louis XVI', 'Refers to the style in decoration that emerged in the 1750s and dominated during the rule of Louis XVI from 1774 to 1792. Also called Louis Seize. AAT 300021271.', '300021271'),
  ('culture.styles.modern_european.regional.french.reign.restauration', 'Restauration', 'Refers to the style in decorative arts in France during the restoration of the Bourbons between 1815 and 1830. Also called Charles X. AAT 300021276.', '300021276'),
  ('culture.styles.modern_european.regional.french.reign.revolutionnaire', 'Revolutionnaire', 'The style and period of the French Revolution, and the times preceding and following it. AAT 300386946.', '300386946'),
  ('culture.styles.modern_european.regional.french.reign.second_empire', 'Second Empire', 'Refers to the architectural and decorative arts style in France between 1852 and 1870 under Napoleon III, also affecting Europe and the United States. Also called French Second Empire, Mansard Style. AAT 300021279.', '300021279'),
  ('culture.styles.modern_european.regional.german.architecture.rundbogenstil', 'Rundbogenstil', 'Refers to the style of architecture developed in Germany in the mid-19th century. Also called Round Arch Style. AAT 300021329.', '300021329'),
  ('culture.styles.modern_european.regional.german.ceramics.bunzlau', 'Bunzlau', 'Used to describe ceramics originating from the town of the same name, dating from the Middle Ages. Also called Buntzlau. AAT 300105650.', '300105650'),
  ('culture.styles.modern_european.regional.german.ceramics.kelsterbach', 'Kelsterbach', 'Refers to the style of ceramics produced by the German factory of the same name, established in 1758. AAT 300105664.', '300105664'),
  ('culture.styles.modern_european.regional.german.ceramics.thuringian', 'Thuringian', 'Refers to the style of ceramics originating in the German region of Thuringia and manufactured since the mid 18th century. AAT 300105675.', '300105675'),
  ('culture.styles.modern_european.regional.german.fine_arts.capitalist_realism', 'Capitalist Realism', 'Refers to the style of painting and graphic design of a small group of German artists, primarily Sigmar Polke, Gerhard Richter, and Konrad Lueg. Also called Capitalist Realist. AAT 300253478.', '300253478'),
  ('culture.styles.modern_european.regional.german.fine_arts.entartete_kunst', 'Entartete Kunst', 'Refers collectively to the styles represented in an exhibition held in Munich in 1937 that were condemned by the National Socialist Party as morally and socially depraved. Also called Degenerate art. AAT 300021341.', '300021341'),
  ('culture.styles.modern_european.regional.german.fine_arts.gedankenmalerei', 'Gedankenmalerei', 'A painting trend of the late 19th century related to Symbolism, sharing that movement''s engagement with emotions and ideas represented in concrete allegory. Also called Thought painting. AAT 300122754.', '300122754'),
  ('culture.styles.modern_european.regional.german.fine_arts.merz', 'Merz', 'Refers to the term used to describe the artistic activities of German artist Kurt Schwitters, who was influenced by the theories of Dada. AAT 300021345.', '300021345'),
  ('culture.styles.modern_european.regional.german.fine_arts.neue_sachlichkeit', 'Neue Sachlichkeit', 'Refers to the satirical movement that developed in German painting in the early 1920s and continued until the rise of National Socialism in the 1930s. Also called New Objectivity, Nouvelle Objectivité. AAT 300056541.', '300056541'),
  ('culture.styles.modern_european.regional.italian.architecture.movimento_italiano_per_l_architettura', 'Movimento Italiano per l''Architettura Razionale', 'Italian architecture movement, active from 1930-1931, and a coalition of Rationalist architects. Also called MIAR, M.I.A.R.. AAT 300265841.', '300265841'),
  ('culture.styles.modern_european.regional.italian.architecture.stile_boito', 'Stile Boito', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Italian styles and movements › Modern Italian architecture styles and movements › Stile Boito. AAT 300021367.', '300021367'),
  ('culture.styles.modern_european.regional.italian.architecture.stile_umberto', 'Stile Umberto', 'Refers to the style and movement in Italy in the late 19th century. Also called Cinquecentismo, Neo-cinquecento. AAT 300021368.', '300021368'),
  ('culture.styles.modern_european.regional.italian.decorative_arts.dantesque', 'Dantesque', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Italian styles and movements › Modern Italian decorative arts styles and movements › Dantesque. AAT 300021371.', '300021371'),
  ('culture.styles.modern_european.regional.italian.fine_arts.aeropittura', 'Aeropittura', 'Refers to the style and movement in Italy during the 1930s and early 1940s promulgated in the Manifesto dell''Aeropittura (1929) by artists such as Giacomo Balla. Also called Aeropainting, Aeropittura futurista. AAT 300122757.', '300122757'),
  ('culture.styles.modern_european.regional.italian.fine_arts.divisionist', 'Divisionism', 'Style of painting employed by a loosely associated group of late 19th-century Italian artists seeking a distinctly Italian avant-garde. AAT 300419440.', '300419440'),
  ('culture.styles.modern_european.regional.italian.fine_arts.metaphysical', 'Metaphysical', 'Art & architecture styles › Modern European styles and movements › Modern European regional styles and movements › Modern Italian styles and movements › Modern Italian fine arts styles and movements › Metaphysical. Also called Arte Metafisica, Pittura Metafisica, Scuola Metafisica. AAT 300021376.', '300021376'),
  ('culture.styles.modern_european.regional.italian.fine_arts.movimento_arte_concreta', 'Movimento arte concreta', 'Italian art movement founded in 1948 and inspired by the Concrete Art style from Switzerland. Also called MAC, M.A.C.. AAT 300265840.', '300265840'),
  ('culture.styles.modern_european.regional.italian.fine_arts.novecento_italiano', 'Novecento italiano', 'Italian fine arts movement originating in 1922, which sought to begin a new, yet traditional, Italian art. Also called Novecento. AAT 300265843.', '300265843'),
  ('culture.styles.modern_european.regional.italian.fine_arts.scapigliatura', 'Scapigliatura', 'Refers to the style and movement in Italian literature and art that flourished in Milan between 1860 and 1870. AAT 300122761.', '300122761'),
  ('culture.styles.modern_european.regional.italian.fine_arts.tactilist', 'Tactilism', 'Refers to the movement and style based on Filippo Tommaso Marinetti''s Manifesto del tattilismo, written in 1921, advocating ''tactile harmonies''. Also called Tattilismo. AAT 300122762.', '300122762'),
  ('culture.styles.modern_european.regional.italian.fine_arts.verismo', 'Verismo', 'Certain Italian sculpture of the mid-19th century. AAT 300122766.', '300122766'),
  ('culture.styles.modern_european.regional.russian.fine_arts.constructivist', 'Constructivism', 'Refers to the art and architectural style and movement concerned mainly with expression by means of constructions, noted as a particularly austere branch of abstract art. AAT 300021393.', '300021393'),
  ('culture.styles.modern_european.regional.russian.fine_arts.cubo_futurist', 'Cubo-Futurism', 'Designates the Russian avant-garde artistic and literary movement and style of the 1910s. Also called Cubofuturism. AAT 300021394.', '300021394'),
  ('culture.styles.modern_european.regional.russian.fine_arts.mir_iskusstva', 'Mir Iskusstva', 'Refers to the style and movement organized and set in theory by Serge Diaghilev in 1898 in a publication called Mir Iskusstva. Also called World of Art, World of Art Movement. AAT 300021414.', '300021414'),
  ('culture.styles.modern_european.regional.russian.fine_arts.primitivist', 'Primitivism', 'Russian art movement, active from about 1905 to 1920, which combined influences from Russian folk art with ideas borrowed from Cubism and Futurism. AAT 300174254.', '300174254'),
  ('culture.styles.modern_european.regional.russian.fine_arts.productivist', 'Productivism', 'A trend in post-revolutionary Soviet art in the 1920s and 1930s that promoted a fusion of artistic practice and industrial production. AAT 300417413.', '300417413'),
  ('culture.styles.modern_european.regional.russian.fine_arts.rayonist', 'Rayonism', 'Refers to the style and movement conceived by Mikhail Larionov. Also called Rayism, Rayist. AAT 300021397.', '300021397'),
  ('culture.styles.modern_european.regional.russian.fine_arts.socialist_realist', 'Socialist Realism', 'Representational style sanctioned by the government in Communist countries. AAT 300021404.', '300021404'),
  ('culture.styles.modern_european.regional.russian.fine_arts.suprematist', 'Suprematism', 'Refers to the first movement of pure geometric abstraction in painting, originated by Kasimir Malevich around 1913. AAT 300021405.', '300021405'),
  ('culture.styles.modern_european.regional.russian.fine_arts.unist', 'Unism', 'Refers to the style and movement heavily influenced by the Suprematist school, featuring textured, monochrome compositions and geometric divisions of canvas space. AAT 300108270.', '300108270'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.ceramics.alla_damaschina', 'Alla damaschina', 'Refers to a style of blue-and-white pottery decoration done in Italy beginning in the 15th century in imitation of Damascus wares. AAT 300265246.', '300265246'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.ceramics.alla_porcellana', 'Alla porcellana', 'Style of blue-and-white decoration on maiolica in imitation of 15th-century Chinese wares. AAT 300265245.', '300265245'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.decorative_arts.glassware.anglo_venetian', 'Anglo-Venetian', 'Venetian-type glass style, popular in England during the 16th and 17th centuries. AAT 300264851.', '300264851'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.architecture', 'British Renaissance-Baroque architecture styles', 'Architecture styles belonging to British Renaissance-Baroque cultures. Also called British Renaissance-Baroque architecture style. AAT 300112476.', '300112476'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.british_colonial', 'British Colonial', 'Culture, period, and styles in the British colonies, typically featuring a combination of British and native characteristics. AAT 300192167.', '300192167'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.english_baroque', 'English Baroque', 'Style of art in England during the Baroque period, dating from the late 17th century. AAT 300444307.', '300444307'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.english_renaissance', 'English Renaissance', 'Style and movement in England associated with the European Renaissance that started in Italy in the late 14th century. AAT 300444895.', '300444895'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign', 'British Renaissance-Baroque by reign', 'Art & architecture styles › Renaissance-Baroque styles and periods › Renaissance-Baroque styles › Renaissance-Baroque regional styles › British Renaissance-Baroque styles › British Renaissance-Baroque by reign. AAT 300112604.', '300112604'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.eastern_european.ceramics', 'Eastern European Renaissance-Baroque ceramics styles', 'Ceramics styles belonging to Eastern European Renaissance-Baroque cultures. Also called Eastern European Renaissance-Baroque ceramics style. AAT 300107027.', '300107027'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts', 'French Renaissance-Baroque decorative arts styles', 'Decorative arts styles belonging to French Renaissance-Baroque cultures. Also called French Renaissance-Baroque decorative arts style. AAT 300105686.', '300105686'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.french_colonial', 'French Colonial', 'Refers to the style of artistic production in French colonies featuring a combination of French and native characteristics. AAT 300107024.', '300107024'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.french_renaissance', 'French Renaissance', 'Style, particularly of architecture, incorporating classical elements and designs that developed in the Renaissance period in France. AAT 300404740.', '300404740'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german.ceramics', 'German Renaissance-Baroque ceramics styles', 'Ceramics styles belonging to German Renaissance-Baroque cultures. Also called German Renaissance-Baroque ceramics style. AAT 300103380.', '300103380'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german.danube_style', 'Danube style', 'Refers to a style of painting that developed in Regensburg, Germany, and elsewhere along the Danube river during the Renaissance and Reformation. Also called Danube School, Donaustil. AAT 300263782.', '300263782'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german.german_colonial', 'German Colonial', 'Refers to the style of artistic production in German colonies featuring a combination of German and native characteristics. AAT 300448847.', '300448847'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.barocchetto', 'Barocchetto', 'Refers to the style of 18th-century Italian architecture and sculpture associated with the Rococo and characterized as lighthearted, imaginative, elegant and decorative. AAT 300021105.', '300021105'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.broad_manner', 'Broad Manner', 'Refers to the style of 15th-century Italian engraving that uses bold thick lines producing the effect of a pen drawing. AAT 300041503.', '300041503'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.ceramics', 'Italian Renaissance-Baroque ceramics styles', 'Ceramics styles belonging to Italian Renaissance-Baroque cultures. Also called Italian Renaissance-Baroque ceramics style. AAT 300021114.', '300021114'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.fine_manner', 'Fine Manner', 'Refers to the style of Italian 15th-century engraving that uses fine close lines and some cross-hatching to produce an effect of tonal gradation similar to a wash drawing. AAT 300041506.', '300041506'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.venetian_school', 'Venetian School', 'The style of Renaissance Venice beginning in the late 1400s, led by the brothers Giovanni and Gentile Bellini. AAT 300440789.', '300440789'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.veneto_saracenic', 'Veneto-Saracenic', 'Refers to works produced in Venice by Muslims and by Italian craftsmen trained in the Islamic style. AAT 300264951.', '300264951'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.anglo_netherlandish', 'Anglo-Netherlandish', 'Style that reflects the cross-cultural influence between England and the Netherlands in art and architecture, primarily from the 15th through 17th centuries. AAT 300419387.', '300419387'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.ceramics', 'Netherlandish Renaissance-Baroque ceramics styles', 'Ceramics styles belonging to Netherlandish Renaissance-Baroque cultures. Also called Netherlandish Renaissance-Baroque ceramics style. AAT 300106356.', '300106356'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.delft_school', 'Delft School', 'A mid-17th century Dutch genre painting tendency depicting domestic life, interiors, and street life of Delft. AAT 300440777.', '300440777'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.dutch_colonial', 'Dutch Colonial', 'Refers to the style of artistic production in Dutch colonies featuring a combination of Dutch and native characteristics. AAT 300107022.', '300107022'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.dutch_golden_age', 'Dutch Golden Age', 'In Dutch history, the century from the Twelve Years'' Truce in 1609 to about 1702. Also called Golden Age. AAT 300440791.', '300440791'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.flemish_renaissance_revival', 'Flemish Renaissance Revival', 'Revival architectural style inspired by the 17th-century architecture of Belgium. Also called Flemish Revival. AAT 300444350.', '300444350'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.portuguese.portuguese_colonial', 'Portuguese Colonial', 'Generally refers to the style of art and architecture in Portuguese possessions in south and east Asia and in Brazil during the 16th and 18th centuries. AAT 300107030.', '300107030'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish.churrigueresque', 'Churrigueresque', 'Refers to the style of art and architectural ornament seen primarily in the late 17th through late 18th centuries, principally in Spain and its American colonies. AAT 300132977.', '300132977'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish.herreran', 'Herreran', 'Refers to a style that developed in the second half of the 16th century in Spain and its colonies, and lasted through the 17th century. Also called estilo desornamentado. AAT 300021135.', '300021135'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish.plateresque', 'Plateresque', 'Refers to a style in Spanish and Spanish Colonial architecture and ornament in the 15th and 16th centuries. Also called Plateresco. AAT 300021131.', '300021131'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish.spanish_colonial', 'Spanish Colonial', 'Refers to the style and period from the early 16th century through the early 19th century in areas colonized by Spain, particularly the Americas. Also called Viceregal. AAT 300107033.', '300107033'),
  ('culture.styles.medieval.regional.northern_european.british_isles.architecture.decorated_style', 'Decorated Style', 'Refers to the style that marks the traditional beginning of Gothic style in England around 1290. Also called Second Pointed. AAT 300020799.', '300020799'),
  ('culture.styles.medieval.regional.northern_european.british_isles.architecture.early_english', 'Early English', 'Refers to the beginnings of Gothic architectural style in England, as coined by English architect and antiquarian Thomas Rickman in the early 19th century. Also called Lancet, Early English Gothic, First Pointed. AAT 300020796.', '300020796'),
  ('culture.styles.medieval.regional.northern_european.british_isles.architecture.perpendicular_style', 'Perpendicular Style', 'Refers to the last phase of Gothic architectural style in England, as coined by English architect and antiquarian Thomas Rickman in the early 19th century. Also called Perpendicular, Perpendicular Gothic, Rectilinear Style, Third Pointed. AAT 300020803.', '300020803'),
  ('culture.styles.medieval.regional.northern_european.british_isles.pottery.humber', 'Humber', 'Refers to the style of Medieval glazed pottery in the Humber/Trent river area of northern England, from the 12th century through the 16th century. AAT 300069526.', '300069526'),
  ('culture.styles.medieval.regional.northern_european.french.architecture.angevin_gothic', 'Angevin Gothic', 'Refers to a distinctive style of architecture that developed in the mid-13th century under the Plantagenet English kings'' rule in the Loire Valley. AAT 300020855.', '300020855'),
  ('culture.styles.medieval.regional.northern_european.french.architecture.flamboyant', 'Flamboyant', 'Refers to the last phase of French Gothic architecture, from about 1370 to the 16th century. Also called Flamboyant Gothic, Flamboyant Style, Tertiaire. AAT 300020862.', '300020862'),
  ('culture.styles.medieval.regional.northern_european.french.architecture.rayonnant', 'Rayonnant', 'Refers to the middle phase of French Gothic architecture that flourished during the late 13th through 14th centuries. Also called Rayonnant Gothic, Rayonnant style, Secondaire. AAT 300020859.', '300020859'),
  ('culture.styles.medieval.regional.northern_european.german.architecture.backsteingotik', 'Backsteingotik', 'Refers to the style in architecture and ornament that developed on the north German plain and Baltic coastal cities, primarily during the 13th through the 16th centuries. Also called Backstein Gothic. AAT 300020887.', '300020887'),
  ('culture.styles.medieval.regional.northern_european.german.architecture.fachwerkbau', 'Fachwerkbau', 'Style of timber-framed houses particular to Germany and nearby areas, distinguished by rather small, regular square divisions. AAT 300310216.', '300310216'),
  ('culture.styles.medieval.regional.northern_european.german.architecture.schwellenbau', 'Schwellenbau', 'Style of domestic construction using four horizontal wooden beams (schwellen) that support vertical squared posts. AAT 300310215.', '300310215'),
  ('culture.styles.medieval.regional.northern_european.german.architecture.sondergotik', 'Sondergotik', 'Refers to late Gothic German architecture and art, from the mid-14th century through the mid-16th century. AAT 300020889.', '300020889'),
  ('culture.styles.medieval.regional.northern_european.scandinavian.viking.borre_style', 'Borre Style', 'Refers to a style of Viking art that developed in the later ninth century and lasted to the mid-tenth century. AAT 300263132.', '300263132'),
  ('culture.styles.medieval.regional.northern_european.scandinavian.viking.jellinge_style', 'Jellinge Style', 'Refers to the style of Viking art that is best known from the tenth-century royal Danish monuments and other artifacts at Jelling. Also called Jelling, Jellinge, Jelling Style. AAT 300021010.', '300021010'),
  ('culture.styles.medieval.regional.northern_european.scandinavian.viking.mammen_style', 'Mammen Style', 'Refers to the style of art that flourished in the second half of the tenth century in Scandinavia and at Scandinavian settlements elsewhere in Europe. AAT 300021011.', '300021011'),
  ('culture.styles.medieval.regional.northern_european.scandinavian.viking.oseberg_style', 'Oseberg Style', 'Refers to the style of Viking art named after the eighth-century ship burial at Oseberg in southern Norway. AAT 300263131.', '300263131'),
  ('culture.styles.medieval.regional.northern_european.scandinavian.viking.ringerike_style', 'Ringerike Style', 'Refers to a style of Scandinavian art dating from the 11th century. Also called Ringerike, Ringerike-Style. AAT 300021012.', '300021012'),
  ('culture.styles.medieval.regional.northern_european.scandinavian.viking.urnes_style', 'Urnes Style', 'Refers to a style that developed beginning in the second quarter of the 11th century in Scandinavia and Scandinavian settlements in Ireland and England. Also called Urnes. AAT 300020939.', '300020939'),
  ('culture.styles.medieval.regional.southern_european.italian.pottery.forum', 'Forum', 'Refers to a distinctive style of early Medieval glazed pottery produced in the Roman Campagna. AAT 300021115.', '300021115'),
  ('culture.styles.modern_european.regional.british.decorative_arts.ceramics.minton', 'Minton', 'Refers to the various styles of English porcelain and earthenware produced by Thomas Minton in Staffordshire beginning in 1793. AAT 300060037.', '300060037'),
  ('culture.styles.modern_european.regional.british.decorative_arts.chippendale.chinese_chippendale', 'Chinese Chippendale', 'Refers to English Chinoiserie furniture following the designs published by cabinet maker Thomas Chippendale in 1754. AAT 300021215.', '300021215'),
  ('culture.styles.modern_european.regional.british.reign.victorian.early_victorian', 'Early Victorian', 'Refers to the Victorian style between 1837 and about 1850. AAT 300021233.', '300021233'),
  ('culture.styles.modern_european.regional.british.reign.victorian.folk_victorian', 'Folk Victorian', 'North American architectural style inspired by Victorian style, but made simpler and more plain. AAT 300444355.', '300444355'),
  ('culture.styles.modern_european.regional.british.reign.victorian.high_victorian', 'High Victorian', 'Refers to the Victorian style, mainly in architecture and decorative arts, at its height in the mid-19th century. Also called Victorian Gothic. AAT 300021234.', '300021234'),
  ('culture.styles.modern_european.regional.british.reign.victorian.late_victorian', 'Late Victorian', 'Refers to the Victorian style, mainly in architecture and decorative arts, produced from about 1870 to about 1901. AAT 300021235.', '300021235'),
  ('culture.styles.modern_european.regional.british.revival.elizabethan_revival.elizabethan_gothic_revival', 'Elizabethan Gothic Revival', 'Style of 19th-century architecture and other art that uses elements of Elizabethan and Gothic style. AAT 300444306.', '300444306'),
  ('culture.styles.modern_european.regional.dutch.decorative_arts.ceramics.amstel', 'Amstel', 'Refers to the style of hard-paste porcelain produced by the factory of the same name from 1784 to 1820. AAT 300180700.', '300180700'),
  ('culture.styles.modern_european.regional.french.decorative_arts.ceramics.saint_clement', 'Saint Clément', 'Refers to the style of pottery produced at Saint-Clément beginning in 1758. Also called Saint-Clément. AAT 300106426.', '300106426'),
  ('culture.styles.modern_european.regional.french.decorative_arts.ceramics.sarreguemines', 'Sarreguemines', 'Refers to the style of pottery produced in Lorraine at the Sarreguemines factory beginning in 1778. AAT 300105690.', '300105690'),
  ('culture.styles.modern_european.regional.french.reign.directoire.consulat', 'Consulat', 'Refers to the style of decorative arts from 1799 to 1805 during the First Consul of Napoleon. Also called Consulate. AAT 300021268.', '300021268'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.architecture.artisan_mannerist', 'Artisan Mannerism', 'Refers to the English architectural and decorative style in the mid-17th century. AAT 300108188.', '300108188'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.architecture.black_and_white_style', 'Black and White Style', 'Refers to the style of architecture in the English Midlands characterized by elaborate half-timbering in which the timber is stained black and the plaster in between is painted white. Also called Black and white, Black-and-white. AAT 300021160.', '300021160'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.georgian', 'Georgian', 'Refers to the style in architecture, interior design, and decorative arts in Britain and Ireland, spread to the United States, during the reigns of George I to George IV, between 1714 and 1830. AAT 300021048.', '300021048'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.stuart', 'Stuart', 'Period, culture, and British style under the Stuarts, a Scottish and English dynasty of rulers, patrons, and collectors. Also called Stewart. AAT 300021037.', '300021037'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.tudor', 'Tudor', 'Period, culture, and English style in architecture and decorative arts during the reign of Tudor monarchs from 1485 to 1603. AAT 300021035.', '300021035'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.eastern_european.ceramics.brancovan', 'Brancovan', 'Art & architecture styles › Renaissance-Baroque styles and periods › Renaissance-Baroque styles › Renaissance-Baroque regional styles › Eastern European Renaissance-Baroque styles › Eastern European Renaissance-Baroque ceramics styles › Brancovan. AAT 300021126.', '300021126'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.eastern_european.ceramics.habaner', 'Habaner', 'Refers to the style of pottery made by peasants in Hungary and Moravia (Czech Republic) from the late 16th through the 17th centuries. AAT 300021169.', '300021169'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.aubusson', 'Aubusson', 'Refers to the style of carpets and tapestries produced at the Aubusson factory in France. AAT 300021091.', '300021091'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.ceramics', 'French Renaissance-Baroque ceramics styles', 'Ceramics styles belonging to French Renaissance-Baroque cultures. Also called French Renaissance-Baroque ceramics style. AAT 300105688.', '300105688'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.gobelins', 'Gobelins', 'Refers to the style of French tapestries, ceramics, pietra dura, and other decorative arts produced at the Gobelins manufactory. AAT 300021095.', '300021095'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.reign', 'French Renaissance-Baroque decorative arts styles by reign', 'Art & architecture styles › Renaissance-Baroque styles and periods › Renaissance-Baroque styles › Renaissance-Baroque regional styles › French Renaissance-Baroque styles › French Renaissance-Baroque decorative arts styles › French Renaissance-Baroque decorative arts styles by reign. AAT 300112609.', '300112609'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german.ceramics.bottger', 'Böttger', 'Refers to the style of ceramics produced by Johann Friedrich Böttger in the early 18th century. AAT 300176953.', '300176953'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german.ceramics.hanau', 'Hanau', 'Refers to the style of German faience produced between 1661 and 1806 and largely imitative of blue and white Delft pottery. AAT 300121262.', '300121262'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german.ceramics.regensburg', 'Regensburg', 'Refers to a style of porcelain and interior decoration that developed at the Schloss Sankt Emmeram, the Thurn and Taxis palace in Regensburg, Germany. AAT 300111224.', '300111224'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.german.ceramics.westerwald', 'Westerwald', 'Refers to the style of German pottery produced in an area including Höhr-Grenzhausen and Grenzau after 1590. Also called Nassau. AAT 300105607.', '300105607'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.ceramics.castelli', 'Castelli', 'Refers to the Italian style of pottery produced in the region of Abruzzo in the 17th and 18th centuries. AAT 300107328.', '300107328'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.ceramics.vezzi', 'Vezzi', 'Refers to the style of Italian porcelain produced by Francesco Vezzi in Venice between 1720 and 1729. AAT 300105599.', '300105599'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.veneto_saracenic.mamluk', 'Mamluk', 'Style of a sub-group of Veneto-Saracenic metal wares that includes the bulk of such objects. AAT 300264953.', '300264953'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.veneto_saracenic.turkoman', 'Turkoman', 'Style of a sub-group of Veneto-Saracenic metal wares. AAT 300264952.', '300264952'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.italian.veneto_saracenic.western', 'Western', 'Style of a sub-group of Veneto-Saracenic metal wares. AAT 300264954.', '300264954'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.ceramics.delft', 'Delft', 'Refers to the style of Dutch tin-glazed earthenware produced in Delft beginning in the mid-17th century, characterized by blue and white patterns inspired by imported Chinese porcelain. AAT 300106361.', '300106361'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.ceramics.tournai', 'Tournai', 'Refers to the style of pottery and porcelain produced in Tournai from the 17th century until the 19th century. Also called Tournay. AAT 300106350.', '300106350'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.netherlandish.dutch_colonial.dutch_east_indian', 'Dutch East Indian', 'Styles and culture related to the colonial Dutch East Indies, now Indonesia. Also called Colonial Dutch East-Indian. AAT 300418042.', '300418042'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish.plateresque.first_plateresque', 'First Plateresque', 'Refers to the first distinct phase of Spanish Plateresque style, starting in the late 15th century. Also called Gothic Plateresque. AAT 300107475.', '300107475'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish.plateresque.second_plateresque', 'Second Plateresque', 'Refers to the second distinct phase of Spanish Plateresque style, evident in the first half of the 16th century. Also called Renaissance Plateresque. AAT 300021136.', '300021136'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.spanish.spanish_colonial.colonial_spanish_american', 'Colonial Spanish American', 'Spanish colonial style and period as specifically limited to the Americas. Also called Colonial Latin American. AAT 300343841.', '300343841'),
  ('culture.styles.medieval.regional.northern_european.british_isles.architecture.decorated_style.curvilinear_decorated', 'Curvilinear Decorated', 'Refers to the later phase of the Decorated Style after around 1300, when window tracery moved from geometrical patterns to undulating curves. Also called Curvilinear, Curvilinear Style. AAT 300020801.', '300020801'),
  ('culture.styles.medieval.regional.northern_european.british_isles.architecture.decorated_style.early_decorated', 'Early Decorated', 'Refers to the earlier phase of the decorated style in the late 13th century, when window tracery was composed of geometrical patterns such as circles, arcs of circles, and cusps. Also called Geometrical, Geometrical Decorated. AAT 300020802.', '300020802'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.stuart.caroline', 'Caroline', 'Period and English architectural style during the reigns of Charles I and Charles II between 1625 and 1685. Also called Carolean, English Restoration. AAT 300260970.', '300260970'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.stuart.jacobean', 'Jacobean', 'Period, culture, and English style in architecture and fine and decorative arts during the reign of James I from 1603 to 1625. AAT 300107014.', '300107014'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.stuart.queen_anne', 'Queen Anne', 'Period, culture, and English style in architecture and decorative arts during the reign of Queen Anne from 1702 to 1714 and known for its straightforward simplicity. Also called Queen Anne Style. AAT 300021047.', '300021047'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.stuart.restoration', 'Restoration', 'Period, culture, and English style in architecture and decorative arts from the restoration of Charles II in 1660 to the arrival of William and Mary in 1688. AAT 300113602.', '300113602'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.stuart.william_and_mary', 'William and Mary', 'Period, culture, and English style in architecture and decorative arts during the reign of William III and Mary II between 1688 and 1702. AAT 300021046.', '300021046'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.tudor.elizabethan', 'Elizabethan', 'Period, culture, and English style of architecture and decorative arts produced during the reign of Elizabeth I. AAT 300021036.', '300021036'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.british.reign.tudor.tudor_gothic', 'Tudor Gothic', 'Early Tudor style and period when the influence of Gothic remained strong, particularly evident in domestic architecture. AAT 300444341.', '300444341'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.ceramics.haguenau', 'Haguenau', 'Refers to a style of faïence that developed in the 1720s in Haguenau, Alsace, northeastern France. Also called Hagenau. AAT 300106326.', '300106326'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.ceramics.limoges', 'Limoges', 'Describes French porcelain produced in Limoges beginning in the 18th century. AAT 300106333.', '300106333'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.ceramics.palissy', 'Palissy', 'Refers to the style of French pottery made by Bernard Palissy beginning in the 16th century, decorated with reptiles or mollusks rendered in relief. AAT 300021172.', '300021172'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.ceramics.strasbourg', 'Strasbourg', 'Refers to the style of faience produced at the Strasbourg pottery and porcelain factory in the 18th century. Also called Strasburg, Straßburg. AAT 300106339.', '300106339'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.reign.francois_i', 'François I', 'Refers to the French style of architecture and sculpture during the reign of François I from 1515 to 1547. Also called Francis I, François Premier. AAT 300021072.', '300021072'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.reign.henri_ii', 'Henri II', 'Refers to the period and French style in architecture and decorative arts during the reign of Henri II from 1547 to 1559. Also called Henri Deux. AAT 300107250.', '300107250'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.reign.louis_xiii', 'Louis XIII', 'Refers to the style of French architecture during the reign of Louis XIII from 1610 to 1643 characterized by Renaissance forms and motifs. Also called Louis Treize. AAT 300021078.', '300021078'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.reign.louis_xiv', 'Louis XIV', 'Refers to the style of architecture and decorative arts during the reign of Louis XIV from 1643 to 1715. Also called Louis Quatorze. AAT 300021080.', '300021080'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.reign.louis_xv', 'Louis XV', 'Refers to the style of French interior design and decorative arts between circa 1700 and 1750 during the regency and reign of Louis XV. Also called Louis Quinze. AAT 300021085.', '300021085'),
  ('culture.styles.renaissance_baroque.renaissance_baroque_styles.regional.french.decorative_arts.reign.regence', 'Régence', 'Refers to the French style of architecture and decorative arts between approximately 1710 and 1730. Also called Regency. AAT 300021089.', '300021089')
